import { Graphics } from 'pixi.js';
import type { TerritoryBallJudge } from './TerritoryBallJudge';

// FUN_7ff72baea070 / DAT_7ff72c62a040. This is the native logical-owner
// palette, whose slots 6 and 8 intentionally differ from the sprite palette.
export const TERRITORY_BALL_JUDGE_PALETTE = [
  0x7fbfff,
  0xff8c8c,
  0xffff8c,
  0xa8ffa8,
  0xffb782,
  0xffa8ff,
  0xcf9fff,
  0xe0e0e0,
  0xcfb79f,
  0xffffff,
] as const;

export class TerritoryBallJudgeGridRenderer {
  readonly view = new Graphics();

  constructor() {
    // FUN_7ff72bb44760 registers the callback at native depth +0.1. Native
    // FUN_7ff72bbbd5b0 emits larger depths first, while Pixi renders ascending
    // zIndex, so invert the sign to keep the grid behind depth-0 actors.
    this.view.zIndex = -0.1;
  }

  redraw(judge: TerritoryBallJudge, chipSize: number): void {
    this.view.clear();
    if (!Number.isFinite(chipSize) || chipSize <= 0) return;

    // FUN_7ff72bb45290 scans y outer / x inner, skips signed negative owners,
    // and overlaps adjacent chip-sized fills by 0.5 units to suppress seams.
    for (let cellY = 0; cellY < judge.height; cellY += 1) {
      for (let cellX = 0; cellX < judge.width; cellX += 1) {
        const ownerKey = judge.cellOwners[cellY * judge.width + cellX];
        if (ownerKey < 0) continue;

        this.view.beginFill(
          TERRITORY_BALL_JUDGE_PALETTE[ownerKey] ?? 0x000000,
          1,
        );
        this.view.drawRect(
          cellX * chipSize,
          cellY * chipSize,
          chipSize + 0.5,
          chipSize + 0.5,
        );
        this.view.endFill();
      }
    }
  }
}
