import { Container, Graphics, Sprite } from 'pixi.js';
import { frameTexture } from '../sprites';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface SwitchParams {
  forceClearPressed: boolean;
  broadcastValue: number;
  secondaryTargetLabel: string;
}

const DEFAULT_SWITCH_PARAMS: SwitchParams = {
  forceClearPressed: false,
  broadcastValue: 0,
  secondaryTargetLabel: '',
};

// Recovered-data: DAT_7ff72bcbc930 renders either 16x16 state frame at 2x,
// bottom-centered on the Switch actor anchor.
export const SWITCH_VISUAL_LOCAL_RECT = {
  x: -16,
  y: -32,
  width: 32,
  height: 32,
} as const;

export class Switch {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params: SwitchParams;
  private readonly releasedVisual: Sprite | Graphics;
  private readonly pressedVisual: Sprite | Graphics | undefined;
  pressed = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseSwitchParamsFromSpawn(spawn);
    this.rect = { x: spawn.x - 16, y: spawn.y - 8, width: 32, height: 16 };
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    if (spawn.actorName === 'Switch') {
      this.releasedVisual = createSwitchVisual('switch_released', false);
      this.pressedVisual = createSwitchVisual('switch_pressed', true);
      this.pressedVisual.visible = false;
      this.view.addChild(this.releasedVisual, this.pressedVisual);
    } else {
      // CollisionSwitch and legacy synthetic SwitchMediator rows reuse this
      // browser adapter, but they are not instances of native FUN_7ff72bb5e8c0.
      // Keep their prior presentation until their own renderer data is mined.
      this.releasedVisual = createLegacySwitchVisual();
      this.pressedVisual = undefined;
      this.view.addChild(this.releasedVisual);
    }
  }

  press(): void {
    this.pressed = true;
    if (this.pressedVisual) {
      this.releasedVisual.visible = false;
      this.pressedVisual.visible = true;
    } else {
      this.view.alpha = 0.55;
      this.view.scale.y = 0.65;
    }
  }

  // The engine's plain Switch is MOMENTARY (no latch bit 0x100): it broadcasts a CLOSE event
  // to its target the moment the activator leaves. release() returns the pad to its raised,
  // un-pressed visual so a held-to-open gate can be re-closed.
  release(): void {
    this.pressed = false;
    if (this.pressedVisual) {
      this.releasedVisual.visible = true;
      this.pressedVisual.visible = false;
    } else {
      this.view.alpha = 1;
      this.view.scale.y = 1;
    }
  }
}

function createSwitchVisual(
  frameName: 'switch_released' | 'switch_pressed',
  pressed: boolean,
): Sprite | Graphics {
  const texture = frameTexture(frameName);
  if (texture) {
    const sprite = new Sprite(texture);
    sprite.anchor.set(0.5, 1);
    sprite.scale.set(2);
    return sprite;
  }

  // Browser startup normally supplies the exact atlas frame. Keep the observed
  // pure-red floor dome as a load-failure/headless fallback without scaling the
  // whole actor view (which would distort the native pressed sprite).
  const fallback = new Graphics();
  fallback.beginFill(0xff0000, 1);
  const height = pressed ? 10 : 20;
  fallback.drawRoundedRect(-16, -height, 32, height, height / 2);
  fallback.endFill();
  return fallback;
}

function createLegacySwitchVisual(): Graphics {
  const fallback = new Graphics();
  fallback.beginFill(0xff0000, 1);
  fallback.drawRoundedRect(-16, -6, 32, 20, 9);
  fallback.endFill();
  return fallback;
}

export function parseSwitchParamsFromSpawn(spawn: ActorSpawnDef): SwitchParams {
  return parseSwitchParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseSwitchParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): SwitchParams {
  for (let index = 0; index <= raw.length - 2; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const forceClearPressed = getIntParam(raw[index + 2]) > 0;
    const broadcastValue = getIntParam(raw[index + 3]);
    const secondaryTargetLabel = getStringParam(raw[index + 4]);
    return { forceClearPressed, broadcastValue, secondaryTargetLabel };
  }

  return { ...DEFAULT_SWITCH_PARAMS };
}

function getIntParam(value: ValueAtom | undefined): number {
  return typeof value === 'number' && Number.isFinite(value) ? Math.trunc(value) : 0;
}

function getStringParam(value: ValueAtom | undefined): string {
  return typeof value === 'string' ? value : '';
}

type SwitchGateTarget = { label: string; source: 'explicit' | 'raw' };

export function shouldOpenGateForSwitch(switchSpawn: ActorSpawnDef, gateSpawn: ActorSpawnDef): boolean {
  if (gateSpawn.actorName !== 'Gate' && gateSpawn.actorName !== 'Bridge' && gateSpawn.actorName !== 'KeyBridge') return false;

  const gateLabel = gateSpawn.label.trim();

  for (const target of switchGateTargets(switchSpawn)) {
    if (gateLabel && target.label === gateLabel && !isRawNonGateFamilyTarget(target)) return true;

    const gateTarget = /^(Gate|Bridge|KeyBridge)(.*)$/i.exec(target.label);
    if (gateTarget === null) continue;
    const targetActorName = gateTarget[1];
    const targetLabel = gateTarget[2].trim();
    if (targetLabel) {
      if (
        targetLabel === gateLabel
        && targetActorName.toLowerCase() === gateSpawn.actorName.toLowerCase()
      ) return true;
      continue;
    }
    if (
      (!gateLabel || target.source === 'raw')
      && targetActorName.toLowerCase() === gateSpawn.actorName.toLowerCase()
    ) return true;
  }
  return false;
}

function switchGateTargets(switchSpawn: ActorSpawnDef): SwitchGateTarget[] {
  const targets = new Map<string, SwitchGateTarget>();
  const explicitLabel = switchSpawn.label.trim();
  const rawTargets = new Set<string>();
  let hasRawGateFamilyTarget = false;

  const rawTargetStartIndex = switchRawTargetStartIndex(switchSpawn);
  for (let index = rawTargetStartIndex; index < switchSpawn.raw.length; index += 1) {
    const value = switchSpawn.raw[index];
    if (typeof value !== 'string') continue;
    const label = value.trim();
    if (!label) continue;
    if (isGateFamilyTarget(label)) hasRawGateFamilyTarget = true;
    rawTargets.add(label);
  }

  // Plain Switch rows such as jump02 broadcast both the family label and a later
  // raw secondary target; other switch families keep the older raw-target override.
  const keepPlainSwitchFamilyTarget = switchSpawn.actorName === 'Switch' && isBareGateFamilyTarget(explicitLabel);
  const rawTargetOverridesExplicit =
    rawTargets.size > 0
    && !keepPlainSwitchFamilyTarget
    && (isBareGateFamilyTarget(explicitLabel) || hasRawGateFamilyTarget);
  if (explicitLabel && !rawTargetOverridesExplicit) {
    targets.set(explicitLabel, { label: explicitLabel, source: 'explicit' });
  }
  for (const rawTarget of rawTargets) targets.set(rawTarget, { label: rawTarget, source: 'raw' });

  return [...targets.values()];
}

function isGateFamilyTarget(target: string): boolean {
  return /^(Gate|Bridge|KeyBridge)/i.test(target.trim());
}

function isBareGateFamilyTarget(target: string): boolean {
  return /^(Gate|Bridge|KeyBridge)$/i.test(target.trim());
}

function isRawNonGateFamilyTarget(target: SwitchGateTarget): boolean {
  return target.source === 'raw' && /^(TrafficLight|DeadTimer|StopWatch|SwitchMediator)/i.test(target.label.trim());
}

function switchRawTargetStartIndex(spawn: ActorSpawnDef): number {
  for (let index = 0; index < spawn.raw.length - 1; index += 1) {
    if (spawn.raw[index] === spawn.x && spawn.raw[index + 1] === spawn.y) return index + 2;
  }
  return 6;
}
