import type { Vector2 } from '../types';

export const TERRITORY_BALL_UNOWNED_CELL = -1;

const TERRITORY_JUDGE_RESULT_CHARGE_RATE = Math.fround(426.6666565);
const TERRITORY_JUDGE_RESULT_CHARGE_LIMIT = Math.fround(1920);
const TERRITORY_JUDGE_COHORT_SECONDS = Math.fround(1.5);
const TERRITORY_JUDGE_STATE_IDLE = 0;
const TERRITORY_JUDGE_STATE_CHARGE = 10;
const TERRITORY_JUDGE_STATE_SELECT = 0x14;
const BASE_JUDGE_STATE_IDLE = 0;
const BASE_JUDGE_STATE_CHARGE = 10;
const BASE_JUDGE_STATE_SELECT = 0x14;
const BASE_JUDGE_STATE_RESULT = 0x1e;
const BASE_JUDGE_STATE_RESULT_WAIT = 0x1f;
const BASE_JUDGE_RESULT_VIEW_LIFETIME_SECONDS = Math.fround(5);
const BASE_JUDGE_RESULT_VIEW_FIXED_SECONDS = Math.fround(1 / 30);

interface TerritoryBallSample {
  center: Vector2;
  lastTouchOwnerKey: number;
}

export interface TerritoryBallJudgeResultRow {
  playerArrayIndex: number;
  ownerKey: number;
  cellCount: number;
}

export class TerritoryBallJudge {
  readonly width: number;
  readonly height: number;
  readonly cellOwners: Int32Array;
  resultState = TERRITORY_JUDGE_STATE_IDLE;
  resultTimerSeconds = 0;
  resultRows: TerritoryBallJudgeResultRow[] = [];
  resultCursor = 0;
  baseJudgeState = BASE_JUDGE_STATE_IDLE;
  baseJudgeStateSeconds = 0;
  resultCharge = 0;
  winnerOwnerKey: number | null = null;
  resultIsDraw = false;
  resultCaption = '';
  resultViewActive = false;
  resultViewLifetimeSeconds = Math.fround(-1);

  constructor(width: number, height: number) {
    this.width = boundedMapDimension(width);
    this.height = boundedMapDimension(height);
    this.cellOwners = new Int32Array(this.width * this.height);
    // FUN_7ff72bb44760 initializes every entry to dword 0xffffffff.
    this.cellOwners.fill(TERRITORY_BALL_UNOWNED_CELL);
  }

  recordBallStartOfTick(ball: TerritoryBallSample, chipSize: number): boolean {
    if (ball.lastTouchOwnerKey < 0) return false;
    return this.recordCell(
      nativeCellCoordinate(ball.center.x, chipSize),
      nativeCellCoordinate(ball.center.y, chipSize),
      ball.lastTouchOwnerKey,
    );
  }

  recordCell(cellX: number, cellY: number, ownerKey: number): boolean {
    if (
      !Number.isInteger(cellX)
      || !Number.isInteger(cellY)
      || !Number.isInteger(ownerKey)
      || cellX < 0
      || cellY < 0
      || cellX >= this.width
      || cellY >= this.height
    ) return false;

    // FUN_7ff72bb45ab0 writes the owner key row-major after the bounds check.
    this.cellOwners[cellY * this.width + cellX] = ownerKey;
    return true;
  }

  cellOwnerAt(cellX: number, cellY: number): number {
    if (
      !Number.isInteger(cellX)
      || !Number.isInteger(cellY)
      || cellX < 0
      || cellY < 0
      || cellX >= this.width
      || cellY >= this.height
    ) return TERRITORY_BALL_UNOWNED_CELL;
    return this.cellOwners[cellY * this.width + cellX];
  }

  receiveCommand9(playerOwnerKeys: readonly number[]): void {
    const rows = playerOwnerKeys.map((ownerKey, playerArrayIndex) => {
      let cellCount = 0;
      for (const cellOwner of this.cellOwners) {
        if (cellOwner === ownerKey) cellCount += 1;
      }
      return { playerArrayIndex, ownerKey, cellCount };
    });

    // Raw receiver 0x7ff72bb45180..0x7ff72bb451b7 shifts only when the
    // incoming count is strictly smaller, preserving Stage-player order on ties.
    for (let index = 1; index < rows.length; index += 1) {
      const row = rows[index];
      let insertionIndex = index;
      while (
        insertionIndex > 0
        && row.cellCount < rows[insertionIndex - 1].cellCount
      ) {
        rows[insertionIndex] = rows[insertionIndex - 1];
        insertionIndex -= 1;
      }
      rows[insertionIndex] = row;
    }

    this.resultRows = rows;
    // Base receiver FUN_7ff72bb43670 and the raw subclass receiver both start
    // their one-shot result state machines before FUN_7ff72bb44d70 advances.
    this.baseJudgeState = BASE_JUDGE_STATE_CHARGE;
    this.resultState = TERRITORY_JUDGE_STATE_CHARGE;
    this.resultTimerSeconds = 0;
  }

  advanceResultFrame(dtSeconds: number): boolean {
    if (this.resultState !== TERRITORY_JUDGE_STATE_CHARGE) return false;
    const frameSeconds = Number.isFinite(dtSeconds) ? Math.fround(dtSeconds) : 0;

    // Base Judge FUN_7ff72bb43480 runs first. State 10 charges strictly past
    // 1920 at 426.6666565 units/second before the subclass may select cohorts.
    if (this.baseJudgeState === BASE_JUDGE_STATE_CHARGE) {
      const chargeStep = Math.fround(frameSeconds * TERRITORY_JUDGE_RESULT_CHARGE_RATE);
      this.resultCharge = Math.fround(this.resultCharge + chargeStep);
      if (TERRITORY_JUDGE_RESULT_CHARGE_LIMIT < this.resultCharge) {
        this.baseJudgeState = BASE_JUDGE_STATE_SELECT;
      }
    }

    let decisionComplete = false;
    if (
      this.baseJudgeState === BASE_JUDGE_STATE_SELECT
      && this.resultTimerSeconds >= TERRITORY_JUDGE_COHORT_SECONDS
    ) {
      const lastRowIndex = this.resultRows.length - 1;
      const currentRow = this.resultRows[this.resultCursor];
      const lastRow = this.resultRows[lastRowIndex];

      if (!currentRow || !lastRow) {
        // Native action stages always have a nonzero stable Player roster.
        // Keep malformed browser fixtures deterministic without underflowing.
        this.commitResultDecision(null);
        decisionComplete = true;
      } else if (currentRow.cellCount === lastRow.cellCount) {
        this.commitResultDecision(
          this.resultCursor === lastRowIndex && currentRow.ownerKey >= 0
            ? currentRow.ownerKey
            : null,
        );
        decisionComplete = true;
      } else {
        const cohortCellCount = currentRow.cellCount;
        while (
          this.resultCursor < lastRowIndex
          && this.resultRows[this.resultCursor].cellCount === cohortCellCount
        ) {
          this.eraseOwnerCells(this.resultRows[this.resultCursor].ownerKey);
          this.resultCursor += 1;
        }
        // FUN_7ff72bb44d70 handles only one distinct score cohort per window.
        this.resultTimerSeconds = 0;
      }
    }

    // The native subclass tail adds dt even after a cohort reset or final
    // qword state/timer write, so threshold crossings are consumed next frame.
    this.resultTimerSeconds = Math.fround(this.resultTimerSeconds + frameSeconds);
    return decisionComplete;
  }

  advanceBaseJudgeFrame(dtSeconds: number): void {
    const frameSeconds = Number.isFinite(dtSeconds) ? Math.fround(dtSeconds) : 0;

    if (this.baseJudgeState === BASE_JUDGE_STATE_RESULT) {
      // Recovered-data: common Judge update FUN_7ff72bb43480 presents the
      // decision one actor update after the subclass enters state 0x1e.
      this.resultCaption = this.resultIsDraw ? 'DRAW' : 'WINNER';
      this.resultViewActive = true;
      this.resultViewLifetimeSeconds = BASE_JUDGE_RESULT_VIEW_LIFETIME_SECONDS;
      this.baseJudgeState = BASE_JUDGE_STATE_RESULT_WAIT;
      this.baseJudgeStateSeconds = 0;
    }

    if (this.baseJudgeState !== BASE_JUDGE_STATE_IDLE) {
      this.baseJudgeStateSeconds = Math.fround(this.baseJudgeStateSeconds + frameSeconds);
    }
  }

  advanceResultViewFrame(): boolean {
    if (
      this.baseJudgeState !== BASE_JUDGE_STATE_RESULT_WAIT
      || !this.resultViewActive
    ) {
      return this.resultPresentationComplete;
    }

    this.resultViewLifetimeSeconds = Math.fround(
      this.resultViewLifetimeSeconds - BASE_JUDGE_RESULT_VIEW_FIXED_SECONDS,
    );
    // FUN_7ff72bbeabd0 dismisses only after the newly stored float32 lifetime
    // is strictly negative, leaving the native view active through update 150.
    if (this.resultViewLifetimeSeconds < 0) this.resultViewActive = false;
    return this.resultPresentationComplete;
  }

  get resultPresentationComplete(): boolean {
    return this.baseJudgeState === BASE_JUDGE_STATE_RESULT_WAIT
      && !this.resultViewActive;
  }

  private eraseOwnerCells(ownerKey: number): void {
    for (let cellIndex = 0; cellIndex < this.cellOwners.length; cellIndex += 1) {
      if (this.cellOwners[cellIndex] === ownerKey) {
        this.cellOwners[cellIndex] = TERRITORY_BALL_UNOWNED_CELL;
      }
    }
  }

  private commitResultDecision(winnerOwnerKey: number | null): void {
    this.winnerOwnerKey = winnerOwnerKey;
    this.resultIsDraw = winnerOwnerKey === null;
    // FUN_7ff72bb45b20 and FUN_7ff72bb44d70 qword-reset both state/timer pairs.
    this.baseJudgeState = BASE_JUDGE_STATE_RESULT;
    this.baseJudgeStateSeconds = 0;
    this.resultState = TERRITORY_JUDGE_STATE_SELECT;
    this.resultTimerSeconds = 0;
  }
}

function boundedMapDimension(value: number): number {
  return Number.isFinite(value) ? Math.max(0, Math.trunc(value)) : 0;
}

function nativeCellCoordinate(position: number, chipSize: number): number {
  if (!Number.isFinite(position) || !Number.isFinite(chipSize) || chipSize <= 0) {
    return Number.MIN_SAFE_INTEGER;
  }
  // FUN_7ff72bb39cc0 divides single-precision actor position by chipSize,
  // then uses C/C++ truncation toward zero for the command payload.
  return Math.trunc(Math.fround(Math.fround(position) / Math.fround(chipSize)));
}
