import { Graphics } from 'pixi.js';

export const PICO_BACKGROUND = 0xffffff;
// Observed: sampled #ff864d from Steam World 1-3 captures (2026-07-02 19:22 set).
export const PICO_PLATFORM = 0xff864d;
export const PICO_PLATFORM_DARK = 0xc9693d;
export const PICO_WALL = 0xff8a52;
export const PICO_BLOCK = 0x9aa0a6;
export const PICO_DANGER = 0xe44747;
export const PICO_GHOST = 0xe8e8e8;

export function chipFillColor(chip: string): number | undefined {
  if (chip === 'MC_NON') return undefined;
  if (chip.startsWith('MC_BR')) return 0xb88354;
  if (chip.startsWith('MC_BW')) return PICO_PLATFORM;
  if (chip.startsWith('MC_B')) return 0xb0784f;
  if (chip.startsWith('MC_D')) return PICO_DANGER;
  if (chip === 'MC_BLK') return PICO_BLOCK;
  return PICO_PLATFORM;
}

export interface TileNeighbors {
  up: boolean;
  down: boolean;
  left: boolean;
  right: boolean;
}

// Observed (Steam World 1-3 captures, 2026-07-02): solid chips render as flat
// #ff864d slabs on white with ROUNDED corners only where a corner is exposed —
// adjacent same-fill chips merge seamlessly into one slab; an isolated chip is
// a fully rounded square. No per-chip edge lines (the old subtle grid read as
// a debug view). Implemented as: rounded rect per chip, then square patches
// over each side that has a same-fill neighbor (patches overdraw 0.75px into
// the neighbor to hide fractional-scale seams).
export function drawPicoTile(
  g: Graphics,
  x: number,
  y: number,
  size: number,
  chip: string,
  neighbors?: TileNeighbors,
): void {
  const fill = chipFillColor(chip);
  if (fill === undefined) return;

  const n = neighbors ?? { up: false, down: false, left: false, right: false };
  const radius = Math.round(size * 0.28);
  g.lineStyle(0, 0, 0);
  g.beginFill(fill, 1);
  g.drawRoundedRect(x, y, size, size, radius);
  if (n.up) g.drawRect(x, y - 0.75, size, radius + 0.75);
  if (n.down) g.drawRect(x, y + size - radius, size, radius + 0.75);
  if (n.left) g.drawRect(x - 0.75, y, radius + 0.75, size);
  if (n.right) g.drawRect(x + size - radius, y, radius + 0.75, size);
  g.endFill();
}

export function drawPicoCat(g: Graphics, width: number, height: number, color: number): void {
  const outline = 0x8b8b8b;
  const eye = 0x000000;
  const u = Math.max(2, Math.round(width / 13));
  const bodyY = u * 3;
  const bodyH = height - u * 5;

  g.beginFill(color, 1);
  g.lineStyle(u, outline, 1);
  g.drawPolygon([
    u, bodyY,
    u, u,
    u * 4, bodyY,
    width - u * 4, bodyY,
    width - u, u,
    width - u, bodyY,
    width - u, bodyY + bodyH,
    width * 0.62, bodyY + bodyH,
    width * 0.56, height - u,
    width * 0.44, height - u,
    width * 0.38, bodyY + bodyH,
    u, bodyY + bodyH,
  ]);
  g.endFill();

  g.lineStyle(0, 0, 0);
  g.beginFill(eye, 1);
  g.drawRect(width * 0.28, bodyY + bodyH * 0.32, u * 2, u * 2);
  g.drawRect(width * 0.62, bodyY + bodyH * 0.32, u * 2, u * 2);
  g.endFill();
}
