        const appliedBoxRect = stoppedBySideChip
          ?? stoppedByVerticalChip
          ?? (staticRectCollision?.blocked ? staticRectCollision.rect : undefined)
          ?? (closedGateCollision?.blocked ? closedGateCollision.rect : undefined)
          ?? (trafficLightCollision?.blocked ? trafficLightCollision.rect : undefined)
          ?? (closedBridgeCollision?.blocked ? closedBridgeCollision.rect : undefined)
