function parseCollisionChangePlayerTriggerDimensions(
  spawn: ActorSpawnDef,
): { width: number; height: number; repeat: boolean } | undefined {
  // Recovered-data: FUN_7ff72bb3a300 reads width/height params 0/1 and enables
  // repeat only when optional numeric param 2 is strictly positive.
  for (let index = 0; index <= spawn.raw.length - 4; index += 1) {
    if (spawn.raw[index] !== spawn.x || spawn.raw[index + 1] !== spawn.y) continue;
    const width = spawn.raw[index + 2];
    const height = spawn.raw[index + 3];
    if (isPositiveFiniteNumber(width) && isPositiveFiniteNumber(height)) {
      return { width, height, repeat: isPositiveFiniteNumber(spawn.raw[index + 4]) };
    }
  }
  return undefined;
}

function createControllerInputSlotPermutation(partyCount: number, shuffle: boolean): number[] {
  const permutation = Array.from({ length: partyCount }, (_, inputSlot) => inputSlot);
  if (!shuffle) return permutation;
  for (let index = permutation.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(picoRandom() * (index + 1));
    [permutation[index], permutation[swapIndex]] = [permutation[swapIndex], permutation[index]];
  }
  return permutation;
}

function isPositiveFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

