function findFallbackSpawn(stage: StageDef): { x: number; y: number } {
  const firstOpenIndex = stage.map.table.findIndex((chip) => !chipStyle(chip).solid);
  if (firstOpenIndex >= 0) {
    const x = (firstOpenIndex % stage.map.width) * stage.map.chipSize + stage.map.chipSize / 2;
    const y = Math.floor(firstOpenIndex / stage.map.width) * stage.map.chipSize + stage.map.chipSize / 2;
    return { x, y };
  }
  return { x: stage.map.chipSize, y: stage.map.chipSize };
}

function resolveStageMapVariant(stage: StageDef, chosenCount?: number): StageDef {
  const variants = stage.map.variants;
  const variantByPlayerCount = stage.map.variantByPlayerCount;
  if (!variants || !variantByPlayerCount) return stage;

  const spawnedPlayerCount = stage.createTable.filter((actor) => runtimePlayerActorNames.has(actor.actorName)).length;
  // A chosen party size wins; otherwise fall back to the recovered spawn/limit count.
  const playerCount = Math.max(1, chosenCount ?? Math.max(spawnedPlayerCount, stage.limitPlayer || 0, 1));
  const variantKey = variantByPlayerCount[playerCount - 1];
  const variantTable = variantKey ? variants[variantKey] : undefined;
  if (!variantTable) return stage;

  return {
    ...stage,
    map: {
      ...stage.map,
      table: [...variantTable],
    },
  };
}

function paintActiveMapRects(stage: StageDef, activePartyCount: number): StageDef {
  const activeRows = stage.createTable.filter((spawn) => {
    if (spawn.actorName !== 'MapRect') return false;
    const schedule = rowScheduleFromSpawn(spawn);
    return schedule.time <= 0 && partyCountRowActive(schedule.group, activePartyCount);
  });
  if (activeRows.length === 0) return stage;

  const workingStage = {
    ...stage,
    map: { ...stage.map, table: [...stage.map.table] },
  };
  for (const spawn of activeRows) {
    paintRecoveredMapRect(workingStage.map, spawn);
  }
  return workingStage;
}

function paintRecoveredMapRect(map: MapDef, spawn: ActorSpawnDef): void {
  const paramsStart = rawParamsStartAfterCoordinatePair(spawn);
  const rawParams = spawn.raw.slice(paramsStart, paramsStart + 4);
  if (!rawParams.every((value) => typeof value === 'number' && Number.isFinite(value))) return;
  const [rawX, rawY, rawWidth, rawHeight] = rawParams as number[];
  const cellX = Math.trunc(rawX);
  const cellY = Math.trunc(rawY);
  const width = Math.max(1, Math.trunc(rawWidth));
  const height = Math.max(1, Math.trunc(rawHeight));
  // The only active recovered row is the native general rectangle branch.
  // One-cell cap/run variants remain a separate symbolic-mapping milestone.
  if (width <= 1 || height <= 1) return;

  const rightChip = (y: number): string | undefined => {
    const x = cellX + width;
    if (x < 0 || x >= map.width || y < 0 || y >= map.height) return undefined;
    return map.table[y * map.width + x];
  };
  const write = (x: number, y: number, chip: string): void => {
    if (x < 0 || x >= map.width || y < 0 || y >= map.height) return;
    map.table[y * map.width + x] = chip;
  };

  for (let offsetX = 0; offsetX < width; offsetX += 1) {
    const x = cellX + offsetX;
    const isLeft = offsetX === 0;
    const isRight = offsetX === width - 1;
    write(x, cellY, isLeft ? 'MC_CEL' : isRight && rightChip(cellY) === 'MC_NON' ? 'MC_CER' : 'MC_CEC');
    for (let offsetY = 1; offsetY < height - 1; offsetY += 1) {
      write(x, cellY - offsetY, isLeft ? 'MC_WAL' : isRight ? 'MC_WAR' : 'MC_INC');
    }
    const floorY = cellY - height + 1;
    write(x, floorY, isLeft ? 'MC_FLL' : isRight && rightChip(floorY) === 'MC_NON' ? 'MC_FLR' : 'MC_FLC');
  }
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/** lift-load-carry-agree: a body is on a lift slab when its feet rest on the slab top with their centre over it. */
function feetOnSlab(rect: Rect, slab: Rect): boolean {
  const centre = rect.x + rect.width / 2;
  return Math.abs(rect.y + rect.height - slab.y) <= 0.5
    && centre >= slab.x && centre <= slab.x + slab.width;
}

