export interface ChipStyle {
  color: number;
  alpha: number;
  solid: boolean;
  label?: string;
}

const platform = 0xff7f45;
const platformDark = 0xd86f41;
const block = 0xb0784f;
const danger = 0xe44747;

const palette: Record<string, ChipStyle> = {
  MC_NON: { color: 0xffffff, alpha: 0.0, solid: false },
  MC_INC: { color: platform, alpha: 1.0, solid: true },
  MC_FLC: { color: platform, alpha: 1.0, solid: true, label: 'floor center' },
  MC_CEC: { color: platform, alpha: 1.0, solid: true },
  MC_CEL: { color: platform, alpha: 1.0, solid: true, label: 'ceiling left' },
  MC_CER: { color: platform, alpha: 1.0, solid: true, label: 'ceiling right' },
  MC_WAR: { color: platform, alpha: 1.0, solid: true, label: 'wall right' },
  MC_WAL: { color: platform, alpha: 1.0, solid: true, label: 'wall left' },
  MC_BHC: { color: block, alpha: 1.0, solid: true },
  MC_BWC: { color: block, alpha: 1.0, solid: true },
  MC_BHU: { color: block, alpha: 1.0, solid: true, label: 'one-way ceiling' },
  MC_BHD: { color: block, alpha: 1.0, solid: true, label: 'one-way floor' },
  MC_BWL: { color: block, alpha: 1.0, solid: true, label: 'one-way wall left' },
  MC_BWR: { color: block, alpha: 1.0, solid: true, label: 'one-way wall right' },
  MC_BLK: { color: 0x9aa0a6, alpha: 1.0, solid: true },
  MC_FLL: { color: platform, alpha: 1.0, solid: true, label: 'floor left' },
  MC_FLR: { color: platform, alpha: 1.0, solid: true, label: 'floor right' },
  MC_YUKA: { color: platform, alpha: 1.0, solid: true, label: 'floor' },
  MC_BR1: { color: block, alpha: 1.0, solid: true, label: 'breakable brick strength 1' },
  MC_BR2: { color: block, alpha: 0.95, solid: true, label: 'breakable brick strength 2' },
  MC_BR3: { color: block, alpha: 0.9, solid: true, label: 'breakable brick strength 3' },
  MC_BR4: { color: block, alpha: 0.85, solid: true, label: 'breakable brick strength 4' },
  MC_BR5: { color: block, alpha: 0.8, solid: true, label: 'breakable brick strength 5' },
  MC_IRD: { color: platformDark, alpha: 1.0, solid: true, label: 'ice down-right' },
  MC_ILD: { color: platformDark, alpha: 1.0, solid: true, label: 'ice down-left' },
  MC_IRU: { color: platformDark, alpha: 1.0, solid: true, label: 'ice up-right' },
  MC_ILU: { color: platformDark, alpha: 1.0, solid: true, label: 'ice up-left' },
  MC_ILE: { color: platformDark, alpha: 1.0, solid: true, label: 'ice left edge' },
  MC_IRG: { color: platformDark, alpha: 1.0, solid: true, label: 'ice right gate' },
  MC_IDW: { color: platformDark, alpha: 1.0, solid: true, label: 'ice down wall' },
  MC_DLU: { color: danger, alpha: 1.0, solid: true, label: 'danger left-up' },
  MC_DLD: { color: danger, alpha: 1.0, solid: true, label: 'danger left-down' },
  MC_DRU: { color: danger, alpha: 1.0, solid: true, label: 'danger right-up' },
  MC_DRD: { color: danger, alpha: 1.0, solid: true, label: 'danger right-down' },
};

export function chipStyle(chip: string): ChipStyle {
  if (palette[chip]) return palette[chip];
  if (chip.startsWith('MC_D')) return { color: danger, alpha: 1.0, solid: true, label: 'danger chip' };
  if (chip.startsWith('MC_I')) return { color: platformDark, alpha: 1.0, solid: true, label: 'ice chip' };
  if (chip.startsWith('MC_B')) return { color: block, alpha: 1.0, solid: true };
  if (chip.startsWith('MC_C')) return { color: platform, alpha: 1.0, solid: true };
  return { color: 0xff4fd8, alpha: 0.85, solid: false, label: chip };
}
