import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

const DISTANCE_CONSTRAINT_COMMAND29_FLAG_SLOTS = 10;

export interface DistanceConstraintParams {
  targetLabel: string;
  values: number[];
}

export interface DistanceConstraintLink {
  maxDistance: number;
  secondValue: number;
}

export class DistanceConstraint {
  readonly view = new Container();
  readonly params: DistanceConstraintParams;
  private readonly command29LatchPlayerIndexes = new Set<number>();

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseDistanceConstraintParamsFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0xa7f3d0, 0.2);
    g.lineStyle(2, 0x34d399, 0.9);
    g.drawCircle(0, 0, 10);
    g.moveTo(-14, 0);
    g.lineTo(14, 0);
    g.endFill();
    this.view.addChild(g);
  }

  get command29PlayerIndexes(): number[] {
    return [...this.command29LatchPlayerIndexes].sort((a, b) => a - b);
  }

  receiveCommand29(playerIndex: number): boolean {
    const index = Math.trunc(playerIndex);
    if (!Number.isFinite(index) || index < 0 || index >= DISTANCE_CONSTRAINT_COMMAND29_FLAG_SLOTS) {
      return false;
    }

    this.command29LatchPlayerIndexes.add(index);
    return true;
  }

  hasCommand29Latch(playerIndex: number): boolean {
    return this.command29LatchPlayerIndexes.has(Math.trunc(playerIndex));
  }

  clearCommand29Latches(): void {
    this.command29LatchPlayerIndexes.clear();
  }
}

export function parseDistanceConstraintParamsFromSpawn(spawn: ActorSpawnDef): DistanceConstraintParams {
  const values = parseNumericParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);

  return {
    targetLabel: spawn.label,
    values,
  };
}

export function selectDistanceConstraintLinkForPlayerCount(
  values: readonly number[],
  playerCount: number,
): DistanceConstraintLink | undefined {
  if (values.length === 0) return undefined;

  const activePlayerCount = Math.max(2, Math.trunc(playerCount));
  const maxIndex = 2 * activePlayerCount - 4;
  const secondIndex = 2 * activePlayerCount - 3;
  const resolvedMaxIndex = maxIndex >= 0 && maxIndex < values.length ? maxIndex : 0;
  const resolvedSecondIndex = secondIndex >= 0 && secondIndex < values.length ? secondIndex : 1;

  const maxDistance = values[resolvedMaxIndex];
  const secondValue = values[resolvedSecondIndex];

  return {
    maxDistance: Number.isFinite(maxDistance) ? maxDistance : 0,
    secondValue: Number.isFinite(secondValue) ? secondValue : 0,
  };
}

function parseNumericParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number[] {
  for (let index = raw.length - 2; index >= 0; index -= 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    return raw.slice(index + 2).filter(isFiniteNumber);
  }

  return [];
}

function isFiniteNumber(value: ValueAtom): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}
