import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom, Vector2 } from '../types';

export const JUMP_STAND_WIDTH = 40;
export const JUMP_STAND_HEIGHT = 14;
export const JUMP_STAND_BOUNCE_SPEED = 430;

const JUMP_STAND_CONTACT_WIDTH = 32;
const JUMP_STAND_CONTACT_HEIGHT = 34;

const JUMP_STAND_NATIVE_VELOCITY_SCALE = 60;
const TOP_CONTACT_DEPTH = 8;
const MIN_HORIZONTAL_OVERLAP = 6;
const JUMP_STAND_HALF_WIDTH = JUMP_STAND_WIDTH / 2;
const JUMP_STAND_HALF_HEIGHT = JUMP_STAND_HEIGHT / 2;
const JUMP_STAND_CORNER_RADIUS = 5;
const DEFAULT_LAUNCH_VELOCITY: Vector2 = { x: 0, y: -JUMP_STAND_BOUNCE_SPEED };

export class JumpStand {
  readonly view = new Container();
  readonly rect: Rect;
  readonly launchVelocity: Vector2;

  constructor(x: number, y: number, launchVelocity: Vector2 = DEFAULT_LAUNCH_VELOCITY) {
    this.launchVelocity = { ...launchVelocity };
    this.rect = jumpStandContactRect(x, y);
    this.view.x = x;
    this.view.y = y;

    const g = new Graphics();
    g.beginFill(0x68d391, 1);
    g.lineStyle(2, 0x1f7a3a, 1);
    g.drawRoundedRect(
      -JUMP_STAND_HALF_WIDTH,
      -JUMP_STAND_HALF_HEIGHT,
      JUMP_STAND_WIDTH,
      JUMP_STAND_HEIGHT,
      JUMP_STAND_CORNER_RADIUS,
    );
    g.endFill();
    g.beginFill(0xffffff, 0.9);
    g.lineStyle(0, 0, 0);
    g.drawRoundedRect(-14, -5, 28, 4, 2);
    g.endFill();
    g.beginFill(0x2f855a, 1);
    g.drawRect(-16, 3, 32, 4);
    g.endFill();
    this.view.addChild(g);
  }
}

// Recovered-data: FUN_7ff72bb649a0 creates the shared JumpStand/JumpStandEx
// body from DAT_7ff72bcbd960 = {-16, -34, 32, 34}. The origin is the body's
// bottom center; the existing 40x14 vector presentation remains centered.
export function jumpStandContactRect(x: number, y: number): Rect {
  return {
    x: x - JUMP_STAND_CONTACT_WIDTH / 2,
    y: y - JUMP_STAND_CONTACT_HEIGHT,
    width: JUMP_STAND_CONTACT_WIDTH,
    height: JUMP_STAND_CONTACT_HEIGHT,
  };
}

export function jumpStandLaunchVelocityFromSpawn(spawn: ActorSpawnDef): Vector2 {
  return parseJumpStandLaunchVelocityAfterCoordinatePair(
    spawn.raw,
    spawn.x,
    spawn.y,
    spawn.actorName,
  ) ?? { ...DEFAULT_LAUNCH_VELOCITY };
}

export function parseJumpStandLaunchVelocityAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
  actorName: string,
): Vector2 | undefined {
  const isJumpStandEx = actorName === 'JumpStandEx' || raw.some((value) => value === 'JumpStandEx');

  for (let index = 0; index <= raw.length - 3; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const first = raw[index + 2];
    const second = raw[index + 3];
    if (isJumpStandEx) {
      if (isFiniteNumber(first) && isFiniteNumber(second)) {
        return {
          x: first * JUMP_STAND_NATIVE_VELOCITY_SCALE,
          y: second * JUMP_STAND_NATIVE_VELOCITY_SCALE,
        };
      }
      return undefined;
    }

    if (isFiniteNumber(first)) {
      return { x: 0, y: first * JUMP_STAND_NATIVE_VELOCITY_SCALE };
    }
  }

  return undefined;
}

export function getJumpStandBounceVelocity(jumpStand: { launchVelocity?: Vector2 }): Vector2 {
  return {
    x: 0,
    y: jumpStand.launchVelocity?.y ?? DEFAULT_LAUNCH_VELOCITY.y,
  };
}

export function shouldBouncePlayerFromJumpStand(
  playerRect: Rect,
  playerVelocity: Vector2,
  jumpStandRect: Rect,
  previousPlayerRect?: Rect,
): boolean {
  if (playerVelocity.y < 0) return false;

  const horizontalOverlap = Math.min(playerRect.x + playerRect.width, jumpStandRect.x + jumpStandRect.width)
    - Math.max(playerRect.x, jumpStandRect.x);
  if (horizontalOverlap < MIN_HORIZONTAL_OVERLAP) return false;

  const playerBottom = playerRect.y + playerRect.height;
  const topContact = rectsOverlap(playerRect, jumpStandRect)
    && playerBottom >= jumpStandRect.y
    && playerBottom <= jumpStandRect.y + TOP_CONTACT_DEPTH;

  if (topContact) return true;
  if (!previousPlayerRect) return false;

  const previousPlayerBottom = previousPlayerRect.y + previousPlayerRect.height;
  const crossedPadTop = previousPlayerBottom <= jumpStandRect.y && playerBottom >= jumpStandRect.y;
  const stillApproachingFromAbove = playerRect.y <= jumpStandRect.y;

  return crossedPadTop && stillApproachingFromAbove;
}

function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.width
    && a.x + a.width > b.x
    && a.y < b.y + b.height
    && a.y + a.height > b.y;
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}
