import type { Rect } from './types';

export interface PlayPreviewCameraInput {
  viewportWidth: number;
  viewportHeight: number;
  mapPxW: number;
  mapPxH: number;
  scrollable: boolean;
  playerRect?: Rect;
  playerRects?: readonly Rect[];
  cameraBounds?: Rect;
}

export interface PlayPreviewCameraFrame {
  x: number;
  y: number;
  scale: number;
}

export function computePlayPreviewCameraFrame(input: PlayPreviewCameraInput): PlayPreviewCameraFrame {
  const fit = Math.min(
    input.viewportWidth / Math.max(1, input.mapPxW),
    input.viewportHeight / Math.max(1, input.mapPxH),
    1.25,
  );
  const groupFocusRect = computeFocusRect(input.playerRects);
  const focusRect = computeCentroidFocusRect(input.playerRects) ?? input.playerRect;
  const canScroll = input.scrollable && focusRect !== undefined;
  const multiplayerFit = groupFocusRect && input.playerRects && input.playerRects.length > 1
    ? Math.min(
      input.viewportWidth / Math.max(1, groupFocusRect.width),
      input.viewportHeight / Math.max(1, groupFocusRect.height),
    )
    : 0.75;
  const scrollableMinScale = Math.min(0.75, multiplayerFit);
  const scale = canScroll ? Math.min(1.25, Math.max(scrollableMinScale, fit)) : fit;

  if (canScroll && focusRect) {
    const playerCenterX = (focusRect.x + focusRect.width / 2) * scale;
    const playerCenterY = (focusRect.y + focusRect.height / 2) * scale;
    const xRange = input.cameraBounds
      ? computeCameraAxisRange(input.viewportWidth, input.cameraBounds.x, input.cameraBounds.width, scale)
      : { min: Math.min(12, input.viewportWidth - input.mapPxW * scale - 12), max: 12 };
    const yRange = input.cameraBounds
      ? computeCameraAxisRange(input.viewportHeight, input.cameraBounds.y, input.cameraBounds.height, scale)
      : { min: Math.min(12, input.viewportHeight - input.mapPxH * scale - 12), max: 12 };
    return {
      scale,
      x: clamp(input.viewportWidth / 2 - playerCenterX, xRange.min, xRange.max),
      y: clamp(input.viewportHeight / 2 - playerCenterY, yRange.min, yRange.max),
    };
  }

  return {
    scale,
    x: Math.max(12, (input.viewportWidth - input.mapPxW * scale) / 2),
    y: Math.max(12, (input.viewportHeight - input.mapPxH * scale) / 2),
  };
}

function computeFocusRect(playerRects?: readonly Rect[]): Rect | undefined {
  if (!playerRects || playerRects.length === 0) return undefined;
  const finiteRects = playerRects.filter((rect) => (
    Number.isFinite(rect.x)
    && Number.isFinite(rect.y)
    && Number.isFinite(rect.width)
    && Number.isFinite(rect.height)
  ));
  if (finiteRects.length === 0) return undefined;
  return {
    x: Math.min(...finiteRects.map((rect) => rect.x)),
    y: Math.min(...finiteRects.map((rect) => rect.y)),
    width: Math.max(...finiteRects.map((rect) => rect.x + rect.width)) - Math.min(...finiteRects.map((rect) => rect.x)),
    height: Math.max(...finiteRects.map((rect) => rect.y + rect.height)) - Math.min(...finiteRects.map((rect) => rect.y)),
  };
}

function computeCentroidFocusRect(playerRects?: readonly Rect[]): Rect | undefined {
  if (!playerRects || playerRects.length === 0) return undefined;
  const finiteRects = playerRects.filter((rect) => (
    Number.isFinite(rect.x)
    && Number.isFinite(rect.y)
    && Number.isFinite(rect.width)
    && Number.isFinite(rect.height)
  ));
  if (finiteRects.length === 0) return undefined;
  const center = finiteRects.reduce(
    (sum, rect) => ({
      x: sum.x + rect.x + rect.width / 2,
      y: sum.y + rect.y + rect.height / 2,
    }),
    { x: 0, y: 0 },
  );
  return {
    x: center.x / finiteRects.length,
    y: center.y / finiteRects.length,
    width: 0,
    height: 0,
  };
}

function computeCameraAxisRange(viewportSize: number, boundsStart: number, boundsSize: number, scale: number): { min: number; max: number } {
  const scaledStart = boundsStart * scale;
  const scaledSize = boundsSize * scale;
  if (scaledSize <= viewportSize) {
    const centered = (viewportSize - scaledSize) / 2 - scaledStart;
    return { min: centered, max: centered };
  }
  return {
    min: viewportSize - (boundsStart + boundsSize) * scale - 12,
    max: 12 - scaledStart,
  };
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
