import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface BridgeParams {
  width: number;
  height: number;
  offsetX: number;
  offsetY: number;
  direction?: number;
  directionX?: number;
  directionY?: number;
  segmentCount?: number;
  segmentSize?: number;
}

const DEFAULT_BRIDGE_WIDTH = 96;
const DEFAULT_BRIDGE_HEIGHT = 16;
const DEFAULT_BRIDGE_SEGMENT_SIZE = 32;
const ENGINE_AXIS_EPSILON = 1.1920928955078125e-7;

export class Bridge {
  readonly view = new Container();
  readonly rect: Rect;
  private readonly deployedRect: Rect;
  private readonly collapsedRect: Rect;
  readonly params: BridgeParams;
  // Existing collision filters treat opened=true as pass-through. In recovered
  // Bridge segment-command mode, command 9 deploys by returning opened=false.
  private usesSegmentCommands = false;
  opened = false;
  /** bridge-folded-start-and-motion: head distance from the row cell (progress), its target and speed per tick. */
  segmentMotion?: SegmentMotion;
  private partyCount = 2;

  setPartyCount(count: number): void {
    this.partyCount = count;
  }

  isSolid(): boolean {
    return this.segmentMotion ? true : !this.opened;
  }

  extentAt(progress: number): Rect {
    return segmentExtent(this.spawn, this.segmentMotion!, progress);
  }

  applyProgress(progress: number): void {
    if (!this.segmentMotion) return;
    this.segmentMotion.progress = progress;
    Object.assign(this.rect, this.extentAt(progress));
    drawSegmentStrip(this.view, this.rect, this.spawn);
  }

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseBridgeParamsFromSpawn(spawn);
    this.deployedRect = {
      x: spawn.x + this.params.offsetX,
      y: spawn.y + this.params.offsetY,
      width: this.params.width,
      height: this.params.height,
    };
    this.collapsedRect = collapsedBridgeRect(spawn, this.params, this.deployedRect);
    this.rect = { ...this.deployedRect };
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    // Observed (Steam World 1-3 captures 2026-07-02): bridge segments render
    // like every other platform — flat #ff864d with rounded ends — not wood.
    const g = new Graphics();
    const radius = Math.round(Math.min(this.params.width, this.params.height) * 0.28);
    g.lineStyle(0, 0, 0);
    g.beginFill(0xff864d, 1);
    g.drawRoundedRect(this.params.offsetX, this.params.offsetY, this.params.width, this.params.height, radius);
    g.endFill();
    this.view.addChild(g);
  }

  enableSegmentCommandMode(): void {
    if (this.spawn.actorName !== 'Bridge' && this.spawn.actorName !== 'KeyBridge') return;
    this.usesSegmentCommands = true;
    const p = this.params;
    if (p.segmentCount === undefined || p.segmentSize === undefined || p.directionX === undefined || p.directionY === undefined) {
      this.retract();
      return;
    }
    const horizontal = Math.abs(p.directionX) > ENGINE_AXIS_EPSILON;
    const length = p.segmentSize * (p.segmentCount - 1);
    const row = this.spawn.raw.slice(6);
    const preExtension = typeof row[3] === 'number' ? Math.trunc(row[3]) : 0;
    // FUN_7ff72bb72ae0 0x7ff72bb76d0d..0x7ff72bb76d5f: m = trunc(p3 (8 - N) 0.1); 8 - N is unsigned (N > 8 wraps huge).
    const cells = preExtension <= 0 ? 0
      : this.partyCount > 8 ? Infinity
        : Math.trunc(Math.fround(Math.fround(preExtension * (8 - this.partyCount)) * Math.fround(0.1)));
    const start = Math.min(length, cells * p.segmentSize);
    this.segmentMotion = {
      length, progress: start, target: start, speed: 2, dirX: p.directionX, dirY: p.directionY,
      cellW: horizontal ? p.segmentSize + 1 : p.segmentSize, cellH: horizontal ? p.segmentSize : p.segmentSize + 1,
      headPush: typeof row[5] === 'number' && Math.trunc(row[5]) > 0,
    };
    this.opened = true;
    this.applyProgress(start);
  }

  open(): void {
    if (this.usesSegmentCommands) {
      this.deploy();
      return;
    }
    this.opened = true;
    this.view.visible = false;
  }

  close(): void {
    if (this.usesSegmentCommands) {
      this.retract();
      return;
    }
    this.opened = false;
    this.view.visible = true;
  }

  private deploy(): void {
    if (this.segmentMotion) {
      this.segmentMotion.target = this.segmentMotion.length;
      this.segmentMotion.speed = 2;
      this.opened = false;
      return;
    }
    Object.assign(this.rect, this.deployedRect);
    this.opened = false;
    this.view.visible = true;
  }

  private retract(): void {
    if (this.segmentMotion) {
      this.segmentMotion.target = 0;
      this.segmentMotion.speed = 1;
      this.opened = true;
      return;
    }
    Object.assign(this.rect, this.collapsedRect);
    this.opened = true;
    this.view.visible = false;
  }
}

export function parseBridgeParamsFromSpawn(spawn: ActorSpawnDef): BridgeParams {
  return parseBridgeParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y) ?? {
    width: DEFAULT_BRIDGE_WIDTH,
    height: DEFAULT_BRIDGE_HEIGHT,
    offsetX: -DEFAULT_BRIDGE_WIDTH / 2,
    offsetY: -DEFAULT_BRIDGE_HEIGHT / 2,
  };
}

export function parseBridgeParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): BridgeParams | undefined {
  for (let index = 0; index <= raw.length - 3; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const recoveredParams = parseRecoveredBridgeParams(raw, index);
    if (recoveredParams) return recoveredParams;

    const width = raw[index + 2];
    const height = raw[index + 3];
    if (isPositiveFiniteNumber(width) && isPositiveFiniteNumber(height) && !isDirectionComponent(height)) {
      return centeredBridgeParams(width, height);
    }

    if (isPositiveFiniteNumber(width) && isDirectionComponent(height) && raw[index + 4] === undefined) {
      return centeredBridgeParams(width * DEFAULT_BRIDGE_SEGMENT_SIZE, DEFAULT_BRIDGE_HEIGHT, {
        direction: height,
      });
    }
  }

  return undefined;
}

function parseRecoveredBridgeParams(raw: readonly ValueAtom[], coordinateIndex: number): BridgeParams | undefined {
  const segmentCountAtom = raw[coordinateIndex + 2];
  const directionXAtom = raw[coordinateIndex + 3];
  const directionYAtom = raw[coordinateIndex + 4];
  if (
    !isPositiveFiniteNumber(segmentCountAtom)
    || !isFiniteNumber(directionXAtom)
    || !isFiniteNumber(directionYAtom)
  ) {
    return undefined;
  }

  const segmentCount = Math.trunc(segmentCountAtom);
  if (segmentCount <= 0) return undefined;

  const directionLength = Math.hypot(directionXAtom, directionYAtom);
  if (directionLength <= ENGINE_AXIS_EPSILON) return undefined;

  const directionX = directionXAtom / directionLength;
  const directionY = directionYAtom / directionLength;
  const segmentSizeAtom = raw[coordinateIndex + 6];
  const segmentSize = isPositiveFiniteNumber(segmentSizeAtom)
    ? Math.trunc(segmentSizeAtom)
    : DEFAULT_BRIDGE_SEGMENT_SIZE;
  if (segmentSize <= 0) return undefined;

  const horizontalSegment = Math.abs(directionX) > ENGINE_AXIS_EPSILON;
  const segmentWidth = horizontalSegment ? segmentSize + 1 : segmentSize;
  const segmentHeight = horizontalSegment ? segmentSize : segmentSize + 1;
  const endCenterX = directionX * (segmentCount - 1) * segmentSize;
  const endCenterY = directionY * (segmentCount - 1) * segmentSize;
  const minX = Math.min(0, endCenterX);
  const maxX = Math.max(0, endCenterX) + segmentWidth;
  const minY = Math.min(0, endCenterY);
  const maxY = Math.max(0, endCenterY) + segmentHeight;

  return {
    width: maxX - minX,
    height: maxY - minY,
    offsetX: minX,
    offsetY: minY,
    direction: directionX,
    directionX,
    directionY,
    segmentCount,
    segmentSize,
  };
}

function centeredBridgeParams(
  width: number,
  height: number,
  extra: Partial<Pick<BridgeParams, 'direction' | 'directionX' | 'directionY'>> = {},
): BridgeParams {
  return {
    width,
    height,
    offsetX: -width / 2,
    offsetY: -height / 2,
    ...extra,
  };
}

function collapsedBridgeRect(spawn: ActorSpawnDef, params: BridgeParams, fallback: Rect): Rect {
  if (
    params.segmentCount === undefined
    || params.segmentSize === undefined
    || params.directionX === undefined
    || params.directionY === undefined
  ) return { ...fallback };

  const horizontalSegment = Math.abs(params.directionX) > ENGINE_AXIS_EPSILON;
  const width = horizontalSegment ? params.segmentSize + 1 : params.segmentSize;
  const height = horizontalSegment ? params.segmentSize : params.segmentSize + 1;
  return {
    x: spawn.x,
    y: spawn.y,
    width,
    height,
  };
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function isPositiveFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

function isDirectionComponent(value: ValueAtom | undefined): value is number {
  return isFiniteNumber(value) && value >= -1 && value <= 1;
}

/** bridge-folded-start-and-motion: shared by Bridge / KeyBridge / Gate (FUN_7ff72bb4f630 segment platforms). */
export interface SegmentMotion {
  length: number;
  progress: number;
  target: number;
  speed: number;
  dirX: number;
  dirY: number;
  cellW: number;
  cellH: number;
  headPush: boolean;
}

/** The union of the segments when the head is 'progress' along the direction from the row cell. */
export function segmentExtent(spawn: ActorSpawnDef, motion: SegmentMotion, progress: number): Rect {
  const endX = motion.dirX * progress;
  const endY = motion.dirY * progress;
  return {
    x: spawn.x + Math.min(0, endX),
    y: spawn.y + Math.min(0, endY),
    width: Math.abs(endX) + motion.cellW,
    height: Math.abs(endY) + motion.cellH,
  };
}

/** The 16 px orange cells (atlas (240,576) family) drawn as one rounded strip. */
export function drawSegmentStrip(view: Container, rect: Rect, spawn: ActorSpawnDef): void {
  for (const child of view.removeChildren()) child.destroy();
  const g = new Graphics();
  g.lineStyle(0, 0, 0);
  g.beginFill(0xff864d, 1);
  g.drawRoundedRect(rect.x - spawn.x, rect.y - spawn.y, rect.width, rect.height,
    Math.round(Math.min(rect.width, rect.height) * 0.28));
  g.endFill();
  view.addChild(g);
  view.visible = true;
}
