import { Container, Graphics, Text, TextStyle } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

export const BEST_SCORE_DEFAULT_MODE = 0;
// FUN_7ff72bb32e10: mode 0 uses 0xffff864d; positive param0 mode switches text color to 0xffffffff.
export const BEST_SCORE_DEFAULT_TEXT_COLOR = 0xff864d;
export const BEST_SCORE_PARAM0_TEXT_COLOR = 0xffffff;

export class BestScore {
  readonly view = new Container();
  readonly valueText: Text;
  readonly mode: number;

  constructor(readonly spawn: ActorSpawnDef) {
    this.mode = parseBestScoreModeFromSpawn(spawn);
    const textColor = bestScoreTextColorForMode(this.mode);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const background = new Graphics();
    background.beginFill(0x101820, 0.78);
    background.lineStyle(2, 0xffd166, 0.9);
    background.drawRoundedRect(-42, -12, 84, 24, 4);
    background.endFill();
    this.view.addChild(background);

    const label = new Text('BEST', new TextStyle({
      fill: textColor,
      fontSize: 10,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
      stroke: 0x000000,
      strokeThickness: 3,
    }));
    label.anchor.set(0.5);
    label.y = -5;
    this.view.addChild(label);

    this.valueText = new Text('0', new TextStyle({
      fill: textColor,
      fontSize: 12,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
      stroke: 0x000000,
      strokeThickness: 3,
    }));
    this.valueText.anchor.set(0.5);
    this.valueText.y = 6;
    this.view.addChild(this.valueText);
  }

  setValue(value: number): void {
    this.valueText.text = String(Math.max(0, Math.trunc(value)));
  }
}

export function parseBestScoreModeFromSpawn(spawn: ActorSpawnDef): number {
  return parseBestScoreModeAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseBestScoreModeAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number {
  for (let index = 0; index <= raw.length - 3; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    return nativeBestScoreMode(raw[index + 2]);
  }

  return BEST_SCORE_DEFAULT_MODE;
}

function nativeBestScoreMode(value: ValueAtom | undefined): number {
  return typeof value === 'number' && Number.isFinite(value) && Math.trunc(value) > 0 ? 1 : 0;
}

function bestScoreTextColorForMode(mode: number): number {
  return mode === 0 ? BEST_SCORE_DEFAULT_TEXT_COLOR : BEST_SCORE_PARAM0_TEXT_COLOR;
}
