import { Container, Graphics, Sprite, Text, TextStyle } from 'pixi.js';
import { frameTexture } from '../sprites';
import type { ActorSpawnDef } from '../types';

export const ROULETTE_PRESENTATION_WIDTH = 46;
export const ROULETTE_PRESENTATION_HEIGHT = 58;
export const ROULETTE_SYMBOL_FONT_SIZE = 48;
export const ROULETTE_SYMBOL_COLOR = 0xff864d;

export class RoulettePresentation extends Container {
  private readonly label: Text;

  constructor(spawn: ActorSpawnDef, symbol: string) {
    super();
    this.x = spawn.x;
    this.y = spawn.y;

    // Recovered-data: FUN_7ff72bb5c6e0 installs DAT_7ff72bcbc0f0 as a
    // 23x29 atlas frame rendered at 2x in DAT_7ff72bcbc110 [-23,-29,46,58].
    // The transparent center is intentional; Roulette does not draw the
    // generic gray NormalBox plate/cross used by the old browser fallback.
    const texture = frameTexture('roulette_frame');
    if (texture) {
      const frame = new Sprite(texture);
      frame.anchor.set(0.5);
      frame.scale.set(2);
      this.addChild(frame);
    } else {
      this.addChild(drawRouletteFrameFallback());
    }

    // FUN_7ff72bb5cba0 centers the current option at the actor origin. The
    // native shared renderer uses the Famania bitmap font at 48px in #ff864d;
    // monospace remains the browser fallback until that font atlas is ported.
    this.label = new Text(symbol, new TextStyle({
      fill: ROULETTE_SYMBOL_COLOR,
      fontSize: ROULETTE_SYMBOL_FONT_SIZE,
      fontFamily: 'monospace',
      fontWeight: '400',
      align: 'center',
      strokeThickness: 0,
    }));
    this.label.anchor.set(0.5);
    this.addChild(this.label);
  }

  get text(): string {
    return this.label.text;
  }

  set text(symbol: string) {
    this.label.text = symbol;
  }
}

function drawRouletteFrameFallback(): Graphics {
  const frame = new Graphics();
  const halfWidth = ROULETTE_PRESENTATION_WIDTH / 2;
  const halfHeight = ROULETTE_PRESENTATION_HEIGHT / 2;

  frame.lineStyle(4, ROULETTE_SYMBOL_COLOR, 1);
  frame.drawRect(
    -halfWidth + 2,
    -halfHeight + 2,
    ROULETTE_PRESENTATION_WIDTH - 4,
    ROULETTE_PRESENTATION_HEIGHT - 4,
  );
  frame.lineStyle(4, 0xffffff, 1);
  frame.drawRect(
    -halfWidth + 6,
    -halfHeight + 6,
    ROULETTE_PRESENTATION_WIDTH - 12,
    ROULETTE_PRESENTATION_HEIGHT - 12,
  );
  return frame;
}
