import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

export const SMALL_BOX_NATIVE_SIZE = 48;
export const SMALL_BOX_FALLBACK_SIZE = SMALL_BOX_NATIVE_SIZE;

export interface SmallBoxParams {
  size: number;
}

export class SmallBox {
  readonly view = new Container();
  readonly params?: SmallBoxParams;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseSmallBoxParamsFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const size = this.params?.size ?? SMALL_BOX_FALLBACK_SIZE;
    const half = size / 2;
    const g = new Graphics();
    g.beginFill(0xb88a4a, 0.72);
    g.lineStyle(2, this.params ? 0xffd08a : 0x806348, 0.95);
    g.drawRoundedRect(-half, -half, size, size, Math.max(2, size * 0.15));
    g.endFill();
    g.beginFill(0x5c3b22, 0.45);
    g.drawRect(-half + 3, -1, Math.max(0, size - 6), 2);
    g.drawRect(-1, -half + 3, 2, Math.max(0, size - 6));
    g.endFill();
    this.view.addChild(g);
  }
}

export function parseSmallBoxParamsFromSpawn(spawn: ActorSpawnDef): SmallBoxParams | undefined {
  return parseSmallBoxParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y) ?? { size: SMALL_BOX_NATIVE_SIZE };
}

export function parseSmallBoxParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): SmallBoxParams | undefined {
  for (let index = 0; index <= raw.length - 2; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    return { size: SMALL_BOX_NATIVE_SIZE };
  }

  return undefined;
}
