import { Container, Text, TextStyle } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

export interface RecoveredTextParams {
  message: string;
  fontSize: number;
  fillColor: number;
  strokeColor: number | undefined;
  velocityX: number;
}

export const RECOVERED_TEXT_DEFAULT_FONT_SIZE = 20;
export const MIN_RECOVERED_TEXT_FONT_SIZE = 8;
export const MAX_RECOVERED_TEXT_FONT_SIZE = 72;
// FUN_7ff72bb60150/FUN_7ff72bb602f0: default +0x504=0xffff864d, param2 nonzero -> 0xffffffff.
export const RECOVERED_TEXT_DEFAULT_FILL_COLOR = 0xff864d;
export const RECOVERED_TEXT_PARAM2_FILL_COLOR = 0xffffff;
// FUN_7ff72bb602f0/FUN_7ff72bb60820: param4 nonzero enables the secondary text color at +0x508.
export const RECOVERED_TEXT_DEFAULT_STROKE_COLOR = 0xffffff;
export const RECOVERED_TEXT_PARAM2_STROKE_COLOR = 0xff864d;
// Text param3 writes actor velocity +0x118 in engine MKS units; render positions are pixels.
export const RECOVERED_TEXT_ENGINE_TO_PIXEL_SCALE = 100;
// FUN_7ff72bb60150 initializes the text draw component depth to -0.4;
// FUN_7ff72bb602f0 param5 nonzero raises that component to 0.1.
export const RECOVERED_TEXT_DEFAULT_RENDER_DEPTH = -0.4;
export const RECOVERED_TEXT_PARAM5_RENDER_DEPTH = 0.1;

export class RecoveredText {
  readonly view = new Container();
  readonly message: string;
  readonly fontSize: number;
  readonly velocityX: number;

  constructor(readonly spawn: ActorSpawnDef) {
    const params = parseRecoveredTextParamsFromSpawn(spawn);
    this.message = params.message;
    this.fontSize = params.fontSize;
    this.velocityX = params.velocityX;

    this.view.x = spawn.x;
    this.view.y = spawn.y;
    this.view.zIndex = parseRecoveredTextRenderDepthFromSpawn(spawn);

    const label = new Text(this.message, new TextStyle({
      fill: params.fillColor,
      fontSize: this.fontSize,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'left',
      stroke: params.strokeColor ?? RECOVERED_TEXT_DEFAULT_STROKE_COLOR,
      strokeThickness: params.strokeColor === undefined ? 0 : 1,
    }));
    this.view.addChild(label);
  }

  update(dt: number): void {
    if (this.velocityX === 0) return;
    this.view.x += this.velocityX * dt;
  }
}

export function parseRecoveredTextParamsFromSpawn(spawn: ActorSpawnDef): RecoveredTextParams {
  return parseRecoveredTextParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseRecoveredTextRenderDepthFromSpawn(spawn: ActorSpawnDef): number {
  return parseRecoveredTextRenderDepthAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseRecoveredTextParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): RecoveredTextParams {
  const messageIndex = findRecoveredTextMessageIndex(raw, x, y);
  return messageIndex === undefined
    ? defaultRecoveredTextParams()
    : parseRecoveredTextParamsAtMessageIndex(raw, messageIndex);
}

export function parseRecoveredTextRenderDepthAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number {
  const messageIndex = findRecoveredTextMessageIndex(raw, x, y);
  if (messageIndex === undefined) return RECOVERED_TEXT_DEFAULT_RENDER_DEPTH;
  return parseNativeNonZeroIntFlag(raw[messageIndex + 5])
    ? RECOVERED_TEXT_PARAM5_RENDER_DEPTH
    : RECOVERED_TEXT_DEFAULT_RENDER_DEPTH;
}

function defaultRecoveredTextParams(): RecoveredTextParams {
  return {
    message: '',
    fontSize: RECOVERED_TEXT_DEFAULT_FONT_SIZE,
    fillColor: RECOVERED_TEXT_DEFAULT_FILL_COLOR,
    strokeColor: undefined,
    velocityX: 0,
  };
}

function findNextStringIndex(raw: readonly ValueAtom[], startIndex: number): number | undefined {
  for (let index = startIndex; index < raw.length; index++) {
    if (typeof raw[index] === 'string') return index;
  }
  return undefined;
}

function findRecoveredTextMessageIndex(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number | undefined {
  // Recovered rows commonly begin with a metadata/header coordinate pair before
  // the actor name, e.g. [0, 0, 'Text', '', x, y, message, ...]. Do not treat
  // that leading pair as the actor's coordinate anchor, otherwise Text actors
  // spawned at (0, 0) parse 'Text' as their message.
  for (let index = 1; index <= raw.length - 3; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    return findNextStringIndex(raw, index + 2);
  }

  if (raw[2] === 'Text' && typeof raw[6] === 'string' && hasSymbolicCanonicalCoordinate(raw)) {
    return 6;
  }

  return undefined;
}

function hasSymbolicCanonicalCoordinate(raw: readonly ValueAtom[]): boolean {
  return typeof raw[4] === 'string' || typeof raw[5] === 'string';
}

function parseRecoveredTextParamsAtMessageIndex(
  raw: readonly ValueAtom[],
  messageIndex: number,
): RecoveredTextParams {
  const fontSize = parseImmediateFontSize(raw[messageIndex + 1]);
  const fillColor = parseNativeNonZeroIntFlag(raw[messageIndex + 2])
    ? RECOVERED_TEXT_PARAM2_FILL_COLOR
    : RECOVERED_TEXT_DEFAULT_FILL_COLOR;
  const strokeColor = parseNativeNonZeroIntFlag(raw[messageIndex + 4])
    ? fillColor === RECOVERED_TEXT_PARAM2_FILL_COLOR
      ? RECOVERED_TEXT_PARAM2_STROKE_COLOR
      : RECOVERED_TEXT_DEFAULT_STROKE_COLOR
    : undefined;
  const velocityX = parseNativeVelocityX(raw[messageIndex + 3]);
  return {
    message: raw[messageIndex] as string,
    fontSize: fontSize === undefined
      ? RECOVERED_TEXT_DEFAULT_FONT_SIZE
      : clamp(fontSize, MIN_RECOVERED_TEXT_FONT_SIZE, MAX_RECOVERED_TEXT_FONT_SIZE),
    fillColor,
    strokeColor,
    velocityX,
  };
}

function parseImmediateFontSize(value: ValueAtom | undefined): number | undefined {
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) return undefined;
  const nativeInt = Math.trunc(value);
  return nativeInt > 0 ? nativeInt : undefined;
}

function parseNativeNonZeroIntFlag(value: ValueAtom | undefined): boolean {
  return typeof value === 'number' && Number.isFinite(value) && Math.trunc(value) !== 0;
}

function parseNativeVelocityX(value: ValueAtom | undefined): number {
  return typeof value === 'number' && Number.isFinite(value)
    ? value * RECOVERED_TEXT_ENGINE_TO_PIXEL_SCALE
    : 0;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
