import { Container, Graphics, Sprite } from 'pixi.js';
import { frameTexture, type AtlasFrameName } from '../sprites';

export const DAMAGE_RECT_CAP_SIZE = 32;
export const DAMAGE_RECT_FALLBACK_COLOR = 0xff6262;

const DAMAGE_RECT_FRAME_NAMES = [
  ['damage_rect_0_0', 'damage_rect_1_0', 'damage_rect_2_0'],
  ['damage_rect_0_1', 'damage_rect_1_1', 'damage_rect_2_1'],
  ['damage_rect_0_2', 'damage_rect_1_2', 'damage_rect_2_2'],
] as const satisfies readonly (readonly AtlasFrameName[])[];

export interface DamageRectPatch {
  column: number;
  row: number;
  x: number;
  y: number;
  width: number;
  height: number;
}

export function damageRectNineSliceLayout(width: number, height: number): DamageRectPatch[] {
  if (width <= DAMAGE_RECT_CAP_SIZE || height <= DAMAGE_RECT_CAP_SIZE) return [];

  const farCapWidth = Math.min(DAMAGE_RECT_CAP_SIZE, width - DAMAGE_RECT_CAP_SIZE);
  const farCapHeight = Math.min(DAMAGE_RECT_CAP_SIZE, height - DAMAGE_RECT_CAP_SIZE);
  const columnWidths = [
    DAMAGE_RECT_CAP_SIZE,
    width - DAMAGE_RECT_CAP_SIZE - farCapWidth,
    farCapWidth,
  ];
  const rowHeights = [
    DAMAGE_RECT_CAP_SIZE,
    height - DAMAGE_RECT_CAP_SIZE - farCapHeight,
    farCapHeight,
  ];
  const patches: DamageRectPatch[] = [];
  let y = 0;
  for (let row = 0; row < rowHeights.length; row += 1) {
    let x = 0;
    for (let column = 0; column < columnWidths.length; column += 1) {
      patches.push({ column, row, x, y, width: columnWidths[column], height: rowHeights[row] });
      x += columnWidths[column];
    }
    y += rowHeights[row];
  }
  return patches;
}

export function createDamageRectView(width: number, height: number): Container {
  const view = new Container();
  const patches = damageRectNineSliceLayout(width, height);
  const textures = patches.map((patch) => frameTexture(DAMAGE_RECT_FRAME_NAMES[patch.row][patch.column]));
  if (patches.length === 9 && textures.every((texture) => texture !== undefined)) {
    for (let index = 0; index < patches.length; index += 1) {
      const patch = patches[index];
      const sprite = new Sprite(textures[index]);
      sprite.x = patch.x;
      sprite.y = patch.y;
      sprite.width = patch.width;
      sprite.height = patch.height;
      view.addChild(sprite);
    }
    return view;
  }

  const fallback = new Graphics();
  fallback.beginFill(DAMAGE_RECT_FALLBACK_COLOR, 1);
  fallback.drawRoundedRect(0, 0, width, height, Math.min(16, width / 2, height / 2));
  fallback.endFill();
  view.addChild(fallback);
  return view;
}
