import { frameTexture } from '../sprites';
import { Container, Graphics, Sprite, Text, TextStyle } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom, Vector2 } from '../types';

export const PUSH_BOX_SIZE = 32;

/** Engine default for a push box's weight, expressed as PERCENT-OF-PARTY in hundredths (+0x404). */
export const DEFAULT_PUSH_BOX_WEIGHT_PERCENT = 100;
/** Engine default for a push box's additive offset (+0x408). */
export const DEFAULT_PUSH_BOX_OFFSET = 0;

export interface PushBoxParams {
  width: number;
  height: number;
  /** Percent-of-party in hundredths (engine field +0x404, default 100). */
  weightPercent: number;
  /** Additive offset to the required-player count (engine field +0x408, default 0). */
  offset: number;
}

export interface PushBoxMovement {
  axis: 'x' | 'y';
  sign: number;
  previousRect: Rect;
}

export interface PushBoxCollisionMap {
  rectHitsSolid(rect: Rect, movement?: PushBoxMovement): boolean;
}

export interface PushBoxCollisionResult {
  playerRect: Rect;
  playerVelocity: Vector2;
  boxRects: Rect[];
  blocked: boolean;
  movedBoxIndex?: number;
}

export class PushBox {
  readonly view = new Container();
  rect: Rect;
  /** Where the stage placed this box; it returns here from the sky after a fall. */
  readonly spawnRect: Rect;
  /**
   * Settle/fall state. The engine settles an unsupported box downward (ENGINE_SPEC body-graph:
   * "no support below -> fall/settle"). The port engages this only once a horizontal PUSH has
   * left the box over open space (the W1-2 mechanic: a pillar pushed past the floor edge drops
   * into the pit and lands on the surface below). `falling` latches on while it drops; cleared
   * on landing. Static and switch-lifted boxes are never marked falling, so they're untouched.
   */
  velocityY = 0;
  launchX = 0;
  falling = false;
  /** colorbox-colour-push: the player slot colour that pushes this ColorBox (undefined for other boxes). */
  colorIndex?: number;
  /** normal-small-box-are-pushboxes / colorbox-colour-push: falls when unsupported in every stage (FUN_7ff72bb33890 -> FUN_7ff72bb34c40). */
  nativeFall = false;
  /** head-stack-jump-impulse: a hop handed up from the cat below, applied in the box update. */
  hopRequested = false;
  /** head-stack-jump-impulse: in a hop; lands with the exact-landing resolve. */
  hopping = false;
  /** Whether the box's base center had support last frame — gravity engages only on the
   *  supported -> unsupported transition (a box pushed OFF a ledge), so a box that was never
   *  supported (e.g. an artificial floating test box) is left in place. */
  wasSupported = false;
  /**
   * Weight expressed as PERCENT-OF-PARTY in hundredths (engine field +0x404).
   * Undefined for plain Block actors (no number, no count gate — moves freely).
   */
  readonly weightPercent?: number;
  /** Additive offset applied to the required-player count (engine field +0x408). */
  readonly offset: number;
  private readonly resolvedWidth: number;
  private readonly resolvedHeight: number;
  /** The live countdown number drawn on the box (created lazily for numbered boxes). */
  private countText?: Text;

  constructor(x: number, y: number, width = PUSH_BOX_SIZE, height = PUSH_BOX_SIZE, weightPercent?: number, offset = DEFAULT_PUSH_BOX_OFFSET) {
    this.weightPercent = weightPercent;
    this.offset = offset;
    const resolvedWidth = Number.isFinite(width) && width > 0 ? width : PUSH_BOX_SIZE;
    const resolvedHeight = Number.isFinite(height) && height > 0 ? height : PUSH_BOX_SIZE;
    this.resolvedWidth = resolvedWidth;
    this.resolvedHeight = resolvedHeight;
    // The recovered actor y is the box's FEET (same convention as Player), not its
    // centre. A W1-2 tall box (chip_size*8 = exactly the corridor height) rests with
    // its bottom on the floor row; centring it buried the lower half in the solid floor
    // tile (MC_FLC), so every push destination hit solid and the box could never move.
    this.rect = {
      x: x - resolvedWidth / 2,
      y: y - resolvedHeight,
      width: resolvedWidth,
      height: resolvedHeight,
    };

    this.spawnRect = { ...this.rect };

    // PICO PARK push boxes are white with a thick orange outline (matched to the
    // Steam World 1-2 reference, 2026-06-24), not brown crates with an X.
    const outline = Math.max(3, Math.floor(Math.min(resolvedWidth, resolvedHeight) / 12));
    const g = new Graphics();
    g.beginFill(0xffffff, 1);
    g.lineStyle(outline, 0xff7f45, 1);
    g.drawRoundedRect(0, 0, resolvedWidth, resolvedHeight, 4);
    g.endFill();
    const cornerX = Math.min(24, resolvedWidth / 2);
    const cornerY = Math.min(24, resolvedHeight / 2);
    const widths = [cornerX, resolvedWidth - 2 * cornerX, cornerX];
    const heights = [cornerY, resolvedHeight - 2 * cornerY, cornerY];
    const xs = [0, cornerX, resolvedWidth - cornerX];
    const ys = [0, cornerY, resolvedHeight - cornerY];
    const textures = Array.from({ length: 9 }, (_, i) => frameTexture(('push_box_' + i) as any));
    if (textures.every(Boolean)) {
      g.destroy();
      textures.forEach((texture, i) => {
        const sprite = new Sprite(texture);
        sprite.position.set(xs[i % 3], ys[Math.floor(i / 3)]);
        sprite.width = widths[i % 3]; sprite.height = heights[Math.floor(i / 3)];
        this.view.addChild(sprite);
      });
    } else this.view.addChild(g);
    this.syncView();
  }

  /** True when this box carries a count gate (a numbered box), as opposed to a plain Block. */
  get isNumbered(): boolean {
    return this.weightPercent !== undefined;
  }

  applyRect(rect: Rect): void {
    this.rect = rect;
    this.syncView();
  }

  /**
   * Update the live countdown number drawn on the box. The engine draws
   * `required - currentlyPressing` ("%d") every frame, so the number ticks down
   * as more players push and reaches 0 the instant the box can move. Plain Block
   * boxes (no weight) draw nothing. The Text is created lazily the first time a
   * numbered box needs to show a value.
   */
  setDisplayedCount(value: number): void {
    if (!this.isNumbered) return;
    const text = String(Math.max(0, Math.trunc(value)));
    if (!this.countText) {
      this.countText = new Text(text, new TextStyle({
        fill: 0xff7f45,
        fontFamily: 'Arial, sans-serif',
        fontSize: Math.max(24, Math.floor(Math.min(this.resolvedWidth, this.resolvedHeight) * 0.62)),
        fontWeight: '700',
        stroke: 0xffffff,
        strokeThickness: 3,
      }));
      this.countText.anchor.set(0.5);
      this.countText.x = this.resolvedWidth / 2;
      this.countText.y = this.resolvedHeight / 2;
      this.view.addChild(this.countText);
    } else if (this.countText.text !== text) {
      this.countText.text = text;
    }
  }

  private syncView(): void {
    this.view.x = this.rect.x;
    this.view.y = this.rect.y;
  }
}

/**
 * REQUIRED players to move a push box, scaled by the LIVE player count.
 *
 *   required = ceil((weightPercent / 100) * playerCount) + offset, clamped to >= 0
 *
 * (Engine: FUN_7ff72bb34820.) Default weight 100 => the whole party must push. At
 * 2 players W1-2 weights 30/100/50 give 1/2/1; at 8 players weight 100 gives 8.
 */
export function requiredPushPlayers(weightPercent: number, offset: number, playerCount: number): number {
  const scaled = Math.ceil((weightPercent / 100) * playerCount) + offset;
  return Math.max(0, scaled);
}

export function parsePushBoxParamsFromSpawn(spawn: ActorSpawnDef): PushBoxParams | undefined {
  return parsePushBoxParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y, spawn.label);
}

export function parsePushBoxParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
  _label?: string,
): PushBoxParams | undefined {
  for (let index = 0; index <= raw.length - 5; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const value = raw[index + 2];
    const width = raw[index + 3];
    const height = raw[index + 4];
    if (
      typeof width === 'number'
      && Number.isFinite(width)
      && width > 0
      && typeof height === 'number'
      && Number.isFinite(height)
      && height > 0
    ) {
      // The value-after-xy is the engine's weight/offset property. The engine's
      // property parser splits it: value > 0 sets weightPercent (offset stays 0);
      // value <= 0 leaves weightPercent at the default 100 and stores the value as
      // the additive offset. So a box authored with -1 is NOT immovable — it means
      // weight 100, offset -1. The createTable LABEL is the box's NAME/id (switch
      // links), never its number.
      return { width, height, ...parsePushBoxWeightValue(value) };
    }
  }

  return undefined;
}

/**
 * Split the engine's weight/offset property (the value after the x,y pair) the way
 * the retail property parser does:
 *   value > 0  -> weightPercent = value, offset = 0
 *   value <= 0 -> weightPercent = 100 (default), offset = value
 * Non-numeric values fall back to the defaults (weight 100, offset 0).
 */
export function parsePushBoxWeightValue(value: ValueAtom): { weightPercent: number; offset: number } {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    return { weightPercent: DEFAULT_PUSH_BOX_WEIGHT_PERCENT, offset: DEFAULT_PUSH_BOX_OFFSET };
  }
  if (value > 0) {
    return { weightPercent: value, offset: DEFAULT_PUSH_BOX_OFFSET };
  }
  return { weightPercent: DEFAULT_PUSH_BOX_WEIGHT_PERCENT, offset: value };
}

export function resolvePushBoxCollision(
  previousPlayerRect: Rect,
  currentPlayerRect: Rect,
  playerVelocity: Vector2,
  pushBoxRects: readonly Rect[],
  map: PushBoxCollisionMap,
  // The number drawn on a box is how many players must push together to move it.
  // canMoveBox(index, sign) returns whether enough players are pushing box `index`
  // in direction `sign` this frame. When omitted, boxes move with a single pusher
  // (the existing 1-player behaviour). An under-pushed box still blocks the player
  // (it acts as a solid wall) — it just does not move.
  canMoveBox?: (index: number, sign: number, chain?: { lead: number; bodies: number }) => boolean,
  limitPush?: (index: number, from: Rect, to: Rect) => Rect,
): PushBoxCollisionResult {
  let playerRect = { ...currentPlayerRect };
  const playerVelocityOut = { ...playerVelocity };
  const boxRects = pushBoxRects.map((box) => ({ ...box }));
  let blocked = false;
  let movedBoxIndex: number | undefined;

  for (let i = 0; i < boxRects.length; i++) {
    const box = boxRects[i];
    if (!rectsOverlap(playerRect, box)) continue;
    if (!hasVerticalOverlap(playerRect, box)) continue;

    const previousPlayerRight = previousPlayerRect.x + previousPlayerRect.width;
    const previousPlayerBottom = previousPlayerRect.y + previousPlayerRect.height;
    const boxRight = box.x + box.width;
    const boxTop = box.y;

    if (previousPlayerBottom <= boxTop && playerVelocity.y >= 0) {
      playerRect = { ...playerRect, y: boxTop - playerRect.height };
      playerVelocityOut.y = 0;
      blocked = true;
      continue;
    }

    if (playerVelocity.y < 0 && previousPlayerRect.y >= box.y + box.height - 0.5) {
      playerRect = { ...playerRect, y: box.y + box.height };
      playerVelocityOut.y = 0;
      blocked = true;
      continue;
    }

    let pushDelta = 0;
    let resolvedPlayerX = playerRect.x;

    if (previousPlayerRight <= box.x || (playerVelocity.x > 0 && playerRect.x < box.x)) {
      pushDelta = playerRect.x + playerRect.width - box.x;
      resolvedPlayerX = box.x - playerRect.width;
    } else if (previousPlayerRect.x >= boxRight || (playerVelocity.x < 0 && playerRect.x > box.x)) {
      pushDelta = playerRect.x - boxRight;
      resolvedPlayerX = boxRight;
    } else {
      continue;
    }

    const unlimited = { ...box, x: box.x + pushDelta };
    const destination = limitPush ? limitPush(i, box, unlimited) : unlimited;
    // native-walk-and-push-speed: the pusher is stopped by the box face where the box ends this tick.
    const flushPlayerX = pushDelta > 0 ? destination.x - playerRect.width : destination.x + destination.width;
    const destinationHitsSolid = map.rectHitsSolid(destination, {
      axis: 'x',
      sign: Math.sign(pushDelta),
      previousRect: box,
    });
    const enoughPushers = !canMoveBox || canMoveBox(i, Math.sign(pushDelta));
    const followers = !destinationHitsSolid && enoughPushers
      ? planPushBoxLine(i, destination, Math.sign(pushDelta), boxRects, map, canMoveBox)
      : null;
    if (followers) {
      boxRects[i] = destination;
      for (const [index, rect] of followers) boxRects[index] = rect;
      movedBoxIndex = i;
      resolvedPlayerX = flushPlayerX;
    }

    playerRect = { ...playerRect, x: resolvedPlayerX };
    playerVelocityOut.x = 0;
    blocked = true;
  }

  return { playerRect, playerVelocity: playerVelocityOut, boxRects, blocked, movedBoxIndex };
}

function hasVerticalOverlap(a: Rect, b: Rect): boolean {
  return a.y < b.y + b.height && a.y + a.height > b.y;
}

function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.width
    && a.x + a.width > b.x
    && a.y < b.y + b.height
    && a.y + a.height > b.y;
}

/** colorbox-colour-push: the boxes a pushed box drives in front of it (breadth-first from the lead), or null when a
 *  solid or an under-pushed box ends the line (FUN_7ff72bb343e0). depth = the boxes already moving behind it. */
function planPushBoxLine(
  lead: number,
  leadRect: Rect,
  sign: number,
  boxRects: readonly Rect[],
  map: PushBoxCollisionMap,
  canMoveBox?: (index: number, sign: number, chain?: { lead: number; bodies: number }) => boolean,
): Map<number, Rect> | null {
  const planned = new Map<number, Rect>();
  const frontier: Array<{ rect: Rect; depth: number }> = [{ rect: leadRect, depth: 1 }];
  while (frontier.length > 0) {
    const { rect, depth } = frontier.shift()!;
    for (let index = 0; index < boxRects.length; index += 1) {
      if (index === lead || planned.has(index)) continue;
      const other = boxRects[index];
      if (!rectsOverlap(rect, other) || !hasVerticalOverlap(rect, other)) continue;
      const next = { ...other, x: sign > 0 ? rect.x + rect.width : rect.x - other.width };
      if (map.rectHitsSolid(next, { axis: 'x', sign, previousRect: other })) return null;
      if (canMoveBox && !canMoveBox(index, sign, { lead, bodies: depth })) return null;
      planned.set(index, next);
      frontier.push({ rect: next, depth: depth + 1 });
    }
  }
  return planned;
}
