import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export const WARP_ALL_SIZE = 34;

export interface WarpAllParams {
  destination: { x: number; y: number };
  playerOffset?: { x: number; y: number };
}

export class WarpAll {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params?: WarpAllParams;
  readonly triggerSize: { width: number; height: number };

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseWarpAllParamsFromSpawn(spawn);
    this.triggerSize = parseWarpAllTriggerSizeFromSpawn(spawn);
    this.rect = getWarpAllRect(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    const isInitPos = spawn.actorName === 'WarpAllInitPos';
    g.beginFill(isInitPos ? 0x20351f : 0x321f46, 0.55);
    g.lineStyle(2, this.params ? (isInitPos ? 0x8ee66b : 0xd08cff) : 0x50606a, 0.95);
    g.drawRoundedRect(
      -this.triggerSize.width / 2,
      -this.triggerSize.height / 2,
      this.triggerSize.width,
      this.triggerSize.height,
      Math.min(9, this.triggerSize.width / 4, this.triggerSize.height / 4),
    );
    g.endFill();
    g.beginFill(this.params ? 0xffffff : 0x50606a, 0.45);
    g.drawRect(-12, -2, 24, 4);
    g.drawRect(-2, -12, 4, 24);
    if (!isInitPos) {
      g.drawRect(-8, -8, 16, 4);
      g.drawRect(-8, 4, 16, 4);
    }
    g.endFill();
    this.view.addChild(g);
    this.view.visible = false;
  }
}

export function getWarpAllRect(spawn: ActorSpawnDef): Rect {
  const triggerSize = parseWarpAllTriggerSizeFromSpawn(spawn);
  return {
    x: spawn.x,
    y: spawn.y,
    width: triggerSize.width,
    height: triggerSize.height,
  };
}

export function parseWarpAllTriggerSizeFromSpawn(spawn: ActorSpawnDef): { width: number; height: number } {
  return parseWarpAllTriggerSizeAfterCoordinatePair(spawn.raw, spawn.x, spawn.y) ?? {
    width: WARP_ALL_SIZE,
    height: WARP_ALL_SIZE,
  };
}

export function parseWarpAllTriggerSizeAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): { width: number; height: number } | undefined {
  for (let index = 0; index <= raw.length - 4; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    // Recovered-data: Warp/WarpAll share FUN_7ff72bb62ec0; Lua [2,3] are the sensor AABB.
    const width = raw[index + 2];
    const height = raw[index + 3];
    if (isPositiveFiniteNumber(width) && isPositiveFiniteNumber(height)) {
      return { width, height };
    }
  }

  return undefined;
}

export function parseWarpAllParamsFromSpawn(spawn: ActorSpawnDef): WarpAllParams | undefined {
  // Recovered Lua layouts diverge after the x,y spawn pair:
  //   WarpAll        {..,x,y, width,height, destX,destY, dx,dy} -> dest at +4/+5, player offset at +6/+7
  //   WarpAllInitPos {..,x,y, width,height}                     -> InitPos sensor, no destination
  // (stage_constraint02.lua:28, stage_constraint01_2.lua:25/30, stage_gun03.lua:26, stage_main_menu.lua:23)
  if (spawn.actorName === 'WarpAllInitPos') return undefined;
  return parseWarpAllParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseWarpAllParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): WarpAllParams | undefined {
  // Offsets relative to the matched spawn pair (see parseWarpAllParamsFromSpawn).
  const destOffset = 4;

  for (let index = 0; index <= raw.length - (destOffset + 2); index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const destinationX = raw[index + destOffset];
    const destinationY = raw[index + destOffset + 1];
    if (!isFiniteNumber(destinationX) || !isFiniteNumber(destinationY)) continue;

    let playerOffset: WarpAllParams['playerOffset'];
    const offsetX = raw[index + 6];
    const offsetY = raw[index + 7];
    if (isFiniteNumber(offsetX) && isFiniteNumber(offsetY)) playerOffset = { x: offsetX, y: offsetY };

    return playerOffset ? { destination: { x: destinationX, y: destinationY }, playerOffset }
      : { destination: { x: destinationX, y: destinationY } };
  }

  return undefined;
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function isPositiveFiniteNumber(value: ValueAtom | undefined): value is number {
  return isFiniteNumber(value) && value > 0;
}
