import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

export const DEAD_BALL_PITCHER_DEFAULT_ANGLE_DEGREES = 0;
export const DEAD_BALL_PITCHER_DEFAULT_INTERVAL_SECONDS = 0;
export const PHYSICS_BALL_DEFAULT_MOTION_MAGNITUDE = 5;
export const PHYSICS_BALL_RADIUS = 12;
export const PHYSICS_BALL_DIAMETER = PHYSICS_BALL_RADIUS * 2;
export const PHYSICS_BALL_SPAWN_OFFSET = 20;
const PHYSICS_BALL_PARTY_MAGNITUDE_SCALE = Math.fround(0.1);
const PHYSICS_BALL_ANGLE_HALF_TURN = Math.fround(180);
const PHYSICS_BALL_ANGLE_UNITS_PER_HALF_TURN = Math.fround(32768);
const PHYSICS_BALL_RADIANS_PER_ANGLE_UNIT = Math.fround(0.0000958738019107841);

export class DeadBallPitcher {
  readonly view = new Container();
  private readonly projectile = new Graphics();
  readonly angleDegrees: number;
  readonly intervalSeconds: number;
  readonly physicsBallMotionMagnitude: number;

  constructor(readonly spawn: ActorSpawnDef, activePlayerCount = 1) {
    const params = parseDeadBallPitcherParamsFromSpawn(spawn);
    this.angleDegrees = params.angleDegrees;
    this.intervalSeconds = params.intervalSeconds;
    this.physicsBallMotionMagnitude = spawn.actorName === 'PhysicsBallPitcher'
      ? physicsBallMotionMagnitudeFromSpawn(spawn, activePlayerCount)
      : 0;
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const body = new Graphics();
    body.beginFill(0x35233f, 0.86);
    body.lineStyle(2, 0xff4f6d, 0.95);
    body.drawCircle(0, 0, 10);
    body.endFill();
    body.lineStyle(3, 0xffd166, 0.9);
    body.moveTo(0, 0);
    body.lineTo(18 * Math.cos(degreesToRadians(this.angleDegrees)), 18 * Math.sin(degreesToRadians(this.angleDegrees)));
    this.view.addChild(body);

    const isPhysicsBall = spawn.actorName === 'PhysicsBallPitcher';
    this.projectile.beginFill(0xff4f6d, 0.92);
    this.projectile.lineStyle(2, 0xfff0f3, 0.9, isPhysicsBall ? 1 : 0.5);
    this.projectile.drawCircle(0, 0, isPhysicsBall ? PHYSICS_BALL_RADIUS : 8);
    this.projectile.endFill();
    this.view.addChild(this.projectile);
    this.restoreProjectileOffset();
  }

  setProjectileOffset(x: number, y: number): void {
    this.projectile.x = x;
    this.projectile.y = y;
  }

  setProjectileAppearance(scale: number, alpha: number): void {
    this.projectile.scale.x = scale;
    this.projectile.scale.y = scale;
    this.projectile.alpha = alpha;
  }

  removeProjectile(): void {
    if (this.projectile.parent !== this.view) return;
    const parent = this.view as unknown as {
      children: unknown[];
      removeChild?: (child: Graphics) => void;
    };
    if (typeof parent.removeChild === 'function') {
      parent.removeChild(this.projectile);
      return;
    }
    const childIndex = parent.children.indexOf(this.projectile);
    if (childIndex >= 0) parent.children.splice(childIndex, 1);
    (this.projectile as unknown as { parent: Container | null }).parent = null;
  }

  restoreProjectile(): void {
    this.restoreProjectileOffset();
    this.setProjectileAppearance(1, 1);
    if (this.projectile.parent === this.view) return;
    const parent = this.view as unknown as {
      addChild?: (child: Graphics) => void;
      children: unknown[];
    };
    if (typeof parent.addChild === 'function') {
      parent.addChild(this.projectile);
      return;
    }
    parent.children.push(this.projectile);
    (this.projectile as unknown as { parent: Container | null }).parent = this.view;
  }

  private restoreProjectileOffset(): void {
    if (this.spawn.actorName !== 'PhysicsBallPitcher') {
      this.setProjectileOffset(0, 0);
      return;
    }

    const direction = physicsBallDirectionFromAngle(this.angleDegrees);
    const centerX = Math.fround(
      Math.fround(this.spawn.x)
      + Math.fround(direction.x * PHYSICS_BALL_SPAWN_OFFSET),
    );
    const centerY = Math.fround(
      Math.fround(this.spawn.y)
      + Math.fround(direction.y * PHYSICS_BALL_SPAWN_OFFSET),
    );
    this.setProjectileOffset(centerX - this.spawn.x, centerY - this.spawn.y);
  }
}

export interface DeadBallPitcherParams {
  angleDegrees: number;
  intervalSeconds: number;
}

export function parseDeadBallPitcherParamsFromSpawn(spawn: ActorSpawnDef): DeadBallPitcherParams {
  return parseDeadBallPitcherParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseDeadBallPitcherParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): DeadBallPitcherParams {
  for (let index = 0; index <= raw.length - 4; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    return {
      angleDegrees: finiteNumberOrDefault(raw[index + 2], DEAD_BALL_PITCHER_DEFAULT_ANGLE_DEGREES),
      intervalSeconds: finiteNumberOrDefault(raw[index + 3], DEAD_BALL_PITCHER_DEFAULT_INTERVAL_SECONDS),
    };
  }

  return {
    angleDegrees: DEAD_BALL_PITCHER_DEFAULT_ANGLE_DEGREES,
    intervalSeconds: DEAD_BALL_PITCHER_DEFAULT_INTERVAL_SECONDS,
  };
}

export function physicsBallMotionMagnitudeFromSpawn(
  spawn: ActorSpawnDef,
  activePlayerCount: number,
): number {
  const partyCount = Number.isFinite(activePlayerCount)
    ? Math.max(1, Math.trunc(activePlayerCount))
    : 1;
  if (partyCount === 1) return PHYSICS_BALL_DEFAULT_MOTION_MAGNITUDE;

  const params = paramsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
  const multiplayerGate = params[1];
  if (
    typeof multiplayerGate !== 'number'
    || !Number.isFinite(multiplayerGate)
    || Math.trunc(multiplayerGate) <= 0
  ) {
    return PHYSICS_BALL_DEFAULT_MOTION_MAGNITUDE;
  }

  const selectedPartyValue = params[partyCount - 1];
  const selectedFloat = typeof selectedPartyValue === 'number' && Number.isFinite(selectedPartyValue)
    ? Math.fround(selectedPartyValue)
    : 0;
  return Math.fround(selectedFloat * PHYSICS_BALL_PARTY_MAGNITUDE_SCALE);
}

export function physicsBallDirectionFromAngle(angleDegrees: number): { x: number; y: number } {
  const finiteAngle = Number.isFinite(angleDegrees) ? Math.trunc(angleDegrees) : 0;
  const halfTurns = Math.fround(Math.fround(finiteAngle) / PHYSICS_BALL_ANGLE_HALF_TURN);
  const angleUnits = Math.trunc(Math.fround(
    halfTurns * PHYSICS_BALL_ANGLE_UNITS_PER_HALF_TURN,
  ));
  const radians = Math.fround(
    Math.fround(angleUnits) * PHYSICS_BALL_RADIANS_PER_ANGLE_UNIT,
  );
  return {
    x: Math.fround(Math.sin(radians)),
    y: Math.fround(-Math.cos(radians)),
  };
}

function paramsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): readonly ValueAtom[] {
  for (let index = 0; index <= raw.length - 2; index += 1) {
    if (raw[index] === x && raw[index + 1] === y) return raw.slice(index + 2);
  }
  return [];
}

function finiteNumberOrDefault(value: ValueAtom | undefined, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function degreesToRadians(degrees: number): number {
  return degrees * Math.PI / 180;
}
