import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';
import { PLAYER_RECT_CENTER_OFFSET_X, PLAYER_RECT_CENTER_OFFSET_Y } from './PlayerGeometry';

export const WARP_SIZE = 32;

export interface WarpDestination {
  x: number;
  y: number;
}

export interface WarpPlayerOffset {
  x: number;
  y: number;
}

export interface WarpTriggerSize {
  width: number;
  height: number;
}

export class Warp {
  readonly view = new Container();
  readonly rect: Rect;
  readonly destination?: WarpDestination;
  readonly playerOffset?: WarpPlayerOffset;
  readonly triggerSize: WarpTriggerSize;
  private teleportCounter = 0;

  constructor(readonly spawn: ActorSpawnDef) {
    this.triggerSize = parseWarpTriggerSizeFromSpawn(spawn);
    this.rect = getWarpRect(spawn);
    this.destination = parseWarpDestinationFromSpawn(spawn);
    this.playerOffset = parseWarpPlayerOffsetFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    const isInitPos = spawn.actorName === 'WarpInitPos';
    g.beginFill(isInitPos ? 0x20351f : 0x15364a, 0.55);
    g.lineStyle(2, isInitPos ? 0x8ee66b : this.destination ? 0x66e0ff : 0x50606a, 0.95);
    g.drawRoundedRect(
      -this.triggerSize.width / 2,
      -this.triggerSize.height / 2,
      this.triggerSize.width,
      this.triggerSize.height,
      Math.min(8, this.triggerSize.width / 4, this.triggerSize.height / 4),
    );
    g.endFill();
    g.beginFill(isInitPos ? 0x8ee66b : this.destination ? 0x66e0ff : 0x50606a, 0.35);
    g.drawRect(-10, -3, 20, 6);
    g.drawRect(-3, -10, 6, 20);
    g.endFill();
    this.view.addChild(g);
    this.view.visible = false;
  }

  nextTeleportDestination(playerCount: number): WarpDestination | undefined {
    if (!this.destination) return undefined;

    const playerOffset = this.playerOffset ?? { x: 0, y: 0 };
    const scalar = this.teleportCounter;
    const destination = {
      x: this.destination.x + playerOffset.x * scalar,
      y: this.destination.y + playerOffset.y * scalar,
    };
    const livePlayerCount = Math.max(1, Math.trunc(playerCount));
    this.teleportCounter = (this.teleportCounter % livePlayerCount) + 1;
    return destination;
  }
}

export function getWarpRect(spawn: ActorSpawnDef): Rect {
  const triggerSize = parseWarpTriggerSizeFromSpawn(spawn);
  return {
    x: spawn.x,
    y: spawn.y,
    width: triggerSize.width,
    height: triggerSize.height,
  };
}

export function parseWarpTriggerSizeFromSpawn(spawn: ActorSpawnDef): WarpTriggerSize {
  return parseWarpTriggerSizeAfterCoordinatePair(spawn.raw, spawn.x, spawn.y) ?? {
    width: WARP_SIZE,
    height: WARP_SIZE,
  };
}

export function parseWarpTriggerSizeAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): WarpTriggerSize | undefined {
  for (let index = 0; index <= raw.length - 4; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    // Recovered-data: Warp ctor FUN_7ff72bb62ec0 reads Lua params [2,3] as
    // the sensor AABB width/height; destination remains at [4,5].
    const width = raw[index + 2];
    const height = raw[index + 3];
    if (isPositiveFiniteNumber(width) && isPositiveFiniteNumber(height)) {
      return { width, height };
    }
  }

  return undefined;
}

export function parseWarpDestinationFromSpawn(spawn: ActorSpawnDef): WarpDestination | undefined {
  // Recovered-data: WarpInitPos uses the shared Warp sensor body, but factory
  // FUN_7ff72bb72ae0 never calls the destination setter for InitPos rows.
  if (spawn.actorName === 'WarpInitPos') return undefined;
  return parseWarpDestinationAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseWarpDestinationAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): WarpDestination | undefined {
  for (let index = 0; index <= raw.length - 6; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    // Lua tuple: {..., x, y, width(+2), height(+3), destX(+4), destY(+5), vx(+6), vy(+7)}.
    // The destination is destX/destY, not the trigger-zone width/height.
    const destinationX = raw[index + 4];
    const destinationY = raw[index + 5];
    if (isFiniteNumber(destinationX) && isFiniteNumber(destinationY)) {
      return { x: destinationX, y: destinationY };
    }
  }

  return undefined;
}

export function parseWarpPlayerOffsetFromSpawn(spawn: ActorSpawnDef): WarpPlayerOffset | undefined {
  // Recovered-data: command-8 InitPos sensors do not populate actor+0x3fc.
  if (spawn.actorName === 'WarpInitPos') return undefined;
  return parseWarpPlayerOffsetAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseWarpPlayerOffsetAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): WarpPlayerOffset | undefined {
  for (let index = 0; index <= raw.length - 8; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    // Recovered-data: FUN_7ff72bb78af0 stores Lua [6,7] at actor+0x3fc;
    // FUN_7ff72bb933e0 multiplies that vector by the rotating scalar.
    const offsetX = raw[index + 6];
    const offsetY = raw[index + 7];
    if (isFiniteNumber(offsetX) && isFiniteNumber(offsetY)) {
      return { x: offsetX, y: offsetY };
    }
  }

  return undefined;
}

export function resolveWarpTeleport(playerRect: Rect, destination: WarpDestination): Rect {
  return {
    x: destination.x - PLAYER_RECT_CENTER_OFFSET_X,
    y: destination.y - PLAYER_RECT_CENTER_OFFSET_Y,
    width: playerRect.width,
    height: playerRect.height,
  };
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function isPositiveFiniteNumber(value: ValueAtom | undefined): value is number {
  return isFiniteNumber(value) && value > 0;
}
