export type CatPose = keyof typeof RECOVERED_AVATAR_FRAME_TABLE;

// The shipped player palette, sampled from the atlas's mini cat-head row.
// Order matches the atlas left-to-right (P1 blue, P2 coral, P3 yellow, ...).
export const PICO_PLAYER_PALETTE = [
  0x7fbfff, 0xff8c8c, 0xffff8c, 0xa8ffa8,
  0xffb782, 0xffa8ff, 0xdfbfff, 0xcf9fff,
  0xffddaf, 0xe0e0e0,
] as const;

let atlasCanvas: HTMLCanvasElement | null = null;
let atlasBase: BaseTexture | null = null;
const frameCache = new Map<string, Texture>();
const catCache = new Map<string, Texture>();
const colorChangeCache = new Map<string, Texture>();

export function spritesReady(): boolean {
  return atlasBase !== null;
}

/** Browser-only bootstrap. Never throws; false = keep Graphics fallbacks. */
export async function loadPicoSpriteAtlas(): Promise<boolean> {
  if (atlasBase) return true;
  try {
    const image = new Image();
    image.src = picoAtlasDataUri;
    await image.decode();
    const canvas = document.createElement('canvas');
    canvas.width = image.naturalWidth;
    canvas.height = image.naturalHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return false;
    ctx.drawImage(image, 0, 0);
    atlasCanvas = canvas;
    atlasBase = BaseTexture.from(canvas);
    atlasBase.scaleMode = 0; // NEAREST — crisp pixel art
    return true;
  } catch {
    return false;
  }
}

/** A raw atlas frame as a texture, or undefined when sprites are unavailable. */
export function frameTexture(name: AtlasFrameName): Texture | undefined {
  if (!atlasBase) return undefined;
  let texture = frameCache.get(name);
  if (!texture) {
    const [x, y, w, h] = PICO_ATLAS_FRAMES[name];
    texture = new Texture(atlasBase, new Rectangle(x, y, w, h));
    frameCache.set(name, texture);
  }
  return texture;
}

export function avatarFrameNameForPose(pose: CatPose, trackTime = 0): AtlasFrameName {
  const frames = RECOVERED_AVATAR_FRAME_TABLE[pose];
  if (frames.length === 1) return frames[0];
  const normalizedTime = ((Math.floor(trackTime) % RECOVERED_AVATAR_WALK_TRACK_TICKS)
    + RECOVERED_AVATAR_WALK_TRACK_TICKS) % RECOVERED_AVATAR_WALK_TRACK_TICKS;
  const frameIndex = Math.min(
    Math.floor(normalizedTime / RECOVERED_AVATAR_KEY_STEP_TICKS),
    frames.length - 2,
  );
  return frames[frameIndex];
}

// Channel-key remap: pure red -> body, pure blue -> darkened body (outline),
// pure green -> tongue pink, everything else (face, whites) unchanged.
export function remapCatPixel(
  r: number, g: number, b: number, body: [number, number, number],
): [number, number, number] {
  if (r === 255 && g === 0 && b === 0) return body;
  if (r === 0 && g === 0 && b === 255) {
    return [Math.round(body[0] * 0.45), Math.round(body[1] * 0.45), Math.round(body[2] * 0.45)];
  }
  if (r === 0 && g === 255 && b === 0) return [255, 150, 160];
  return [r, g, b];
}

// Exact recovered color_change_2d.ps channel formula used by native type-6
// modulation: R=body tint, B=0.7*body outline, G=fixed grayscale contribution.
export function remapColorChangePixel(
  r: number, g: number, b: number, body: [number, number, number],
): [number, number, number] {
  const bodyWeight = r / 255 + (b / 255) * 0.7;
  return body.map((channel) => (
    Math.min(255, Math.round(channel * bodyWeight + g))
  )) as [number, number, number];
}

/** A native color_change_2d-remapped frame, cached by atlas frame and tint. */
export function colorChangeFrameTexture(name: AtlasFrameName, bodyColor: number): Texture | undefined {
  if (!atlasCanvas) return undefined;
  const cacheKey = `${bodyColor}:${name}`;
  let texture = colorChangeCache.get(cacheKey);
  if (texture) return texture;

  const [x, y, w, h] = PICO_ATLAS_FRAMES[name];
  const source = atlasCanvas.getContext('2d');
  if (!source) return undefined;
  const data = source.getImageData(x, y, w, h);
  const body: [number, number, number] = [
    (bodyColor >> 16) & 0xff, (bodyColor >> 8) & 0xff, bodyColor & 0xff,
  ];
  const px = data.data;
  for (let i = 0; i < px.length; i += 4) {
    if (px[i + 3] === 0) continue;
    const [nr, ng, nb] = remapColorChangePixel(px[i], px[i + 1], px[i + 2], body);
    px[i] = nr; px[i + 1] = ng; px[i + 2] = nb;
  }
  const out = document.createElement('canvas');
  out.width = w;
  out.height = h;
  out.getContext('2d')?.putImageData(data, 0, 0);
  const base = BaseTexture.from(out);
  base.scaleMode = 0;
  texture = new Texture(base);
  colorChangeCache.set(cacheKey, texture);
  return texture;
}

function bakeCatFrame(frame: AtlasFrameName, bodyColor: number): Texture | undefined {
  if (!atlasCanvas) return undefined;
  const [x, y, w, h] = PICO_ATLAS_FRAMES[frame];
  const source = atlasCanvas.getContext('2d');
  if (!source) return undefined;
  const data = source.getImageData(x, y, w, h);
  const body: [number, number, number] = [
    (bodyColor >> 16) & 0xff, (bodyColor >> 8) & 0xff, bodyColor & 0xff,
  ];
  const px = data.data;
  for (let i = 0; i < px.length; i += 4) {
    if (px[i + 3] === 0) continue;
    const [nr, ng, nb] = remapCatPixel(px[i], px[i + 1], px[i + 2], body);
    px[i] = nr; px[i + 1] = ng; px[i + 2] = nb;
  }
  const out = document.createElement('canvas');
  out.width = w;
  out.height = h;
  out.getContext('2d')?.putImageData(data, 0, 0);
  const base = BaseTexture.from(out);
  base.scaleMode = 0; // NEAREST
  return new Texture(base);
}

/**
 * A recolored cat frame for the given body color, lazily baked and cached.
 * pose + trackTime selects the animation frame in native render-update ticks.
 */
export function catTexture(bodyColor: number, pose: CatPose, trackTime = 0): Texture | undefined {
  if (!atlasCanvas) return undefined;
  const frame = avatarFrameNameForPose(pose, trackTime);
  const cacheKey = `${bodyColor}:${frame}`;
  let texture = catCache.get(cacheKey);
  if (!texture) {
    texture = bakeCatFrame(frame, bodyColor);
    if (!texture) return undefined;
    catCache.set(cacheKey, texture);
  }
  return texture;
}
