import type { Rect, Vector2 } from './types';
import { TileMap } from './TileMap';

export interface CollisionResult {
  rect: Rect;
  velocity: Vector2;
  grounded: boolean;
  hitLeft: boolean;
  hitRight: boolean;
  hitCeiling: boolean;
}

// Sweeps stop a rect at contact; it never enters a tile (native-player-body removed the old floor-rest inset).

export function moveRectWithTileCollisions(
  tileMap: TileMap,
  rect: Rect,
  velocity: Vector2,
  restingOnFloor = false,
): CollisionResult {
  const next: Rect = { ...rect };
  const outVelocity: Vector2 = { ...velocity };
  let grounded = false;
  let hitLeft = false;
  let hitRight = false;
  let hitCeiling = false;

  void restingOnFloor;

  const xSweepRect: Rect = next;
  const xResult = sweepAxis(tileMap, xSweepRect, 'x', velocity.x);
  next.x = xResult.position;
  if (xResult.hit) {
    outVelocity.x = 0;
    hitLeft = velocity.x < 0;
    hitRight = velocity.x > 0;
  }

  // Upward movement off a floor we are resting on ignores the bottom sliver too, so a
  // jump is not cancelled by the floor the feet are embedded in. Downward keeps full height.
  const ySweepRect: Rect = next;
  const yResult = sweepAxis(tileMap, ySweepRect, 'y', velocity.y);
  next.y = yResult.position;
  if (yResult.hit) {
    outVelocity.y = 0;
    grounded = velocity.y > 0;
    hitCeiling = velocity.y < 0;
  }

  return { rect: next, velocity: outVelocity, grounded, hitLeft, hitRight, hitCeiling };
}

function sweepAxis(
  tileMap: TileMap,
  rect: Rect,
  axis: 'x' | 'y',
  distance: number,
): { position: number; hit: boolean } {
  if (distance === 0) return { position: rect[axis], hit: false };

  const sign = Math.sign(distance);
  let remaining = Math.abs(distance);
  let position = rect[axis];

  while (remaining > 0) {
    const step = sign * Math.min(1, remaining);
    const previousRect = { ...rect, [axis]: position };
    const candidate = { ...rect, [axis]: position + step };
    if (tileMap.rectHitsSolid(candidate, { axis, sign, previousRect })) {
      return { position, hit: true };
    }
    position += step;
    rect[axis] = position;
    remaining -= Math.abs(step);
  }

  return { position, hit: false };
}
