import { Container, Graphics, Text, TextStyle } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface StopWatchParams {
  amountSeconds: number;
  controllerName?: string;
  eventValue: number;
  param3Flag: boolean;
}

const STOP_WATCH_SIZE = 22;
const STOP_WATCH_DONE_EPSILON_SECONDS = 1.19e-7;
// Recovered-data: FUN_7ff72bb5e420/FUN_7ff72bb5e5d0 hide param3-flagged timer
// text while remainingSeconds is strictly below DAT_7ff72bc7eb00 (= 3.0).
const STOP_WATCH_PARAM3_LABEL_THRESHOLD_SECONDS = 3;

export class StopWatch {
  readonly view = new Container();
  readonly rect: Rect;
  readonly amountSeconds: number;
  readonly controllerName?: string;
  readonly eventValue: number;
  readonly param3Flag: boolean;
  remainingSeconds: number;
  // Existing browser name retained for compatibility. Native command 9 sets
  // actor+0x3f8 bit0 (paused), while command 10 clears it; therefore true here
  // means the switch has stopped/paused this timer, not that it is running.
  activated = false;
  // Recovered-data: StopWatch command 0x28 stores a presentation payload for
  // Judge loser/result ordering without pausing the underlying timer.
  judgeLoserPresentationPayload: number | null = null;

  readonly displayText: string;

  private readonly body: Graphics;
  private readonly label: Text;

  constructor(readonly spawn: ActorSpawnDef) {
    const params = parseStopWatchParamsFromSpawn(spawn);
    this.amountSeconds = params.amountSeconds;
    this.remainingSeconds = params.amountSeconds;
    this.controllerName = params.controllerName;
    this.eventValue = params.eventValue;
    this.param3Flag = params.param3Flag;
    this.rect = {
      x: spawn.x - STOP_WATCH_SIZE / 2,
      y: spawn.y - STOP_WATCH_SIZE / 2,
      width: STOP_WATCH_SIZE,
      height: STOP_WATCH_SIZE,
    };

    this.view.x = spawn.x;
    this.view.y = spawn.y;

    this.body = new Graphics();
    this.drawBody(0x4fd8ff, 0xffffff, 0.95);
    this.view.addChild(this.body);

    this.displayText = stopWatchDisplayText(spawn.label, this.amountSeconds);
    this.label = new Text(this.displayText, new TextStyle({
      fill: 0x101820,
      fontSize: 9,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
    }));
    this.label.anchor.set(0.5);
    this.label.y = 1;
    this.view.addChild(this.label);
    this.syncLabelVisibility();
  }

  activate(): void {
    if (this.activated) return;
    this.activated = true;
    this.drawBody(0x5f6b73, 0x9aa7b0, 0.75);
    this.view.alpha = 0.65;
    this.label.style = new TextStyle({
      fill: 0xffffff,
      fontSize: 9,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
    });
  }

  // Recovered-data: StopWatch receiver FUN_7ff72bb5e1a0 handles command 10 by
  // clearing only actor+0x3f8 bit0. The remaining time and done bit are kept.
  resume(): void {
    if (!this.activated) return;
    this.activated = false;
    this.drawBody(0x4fd8ff, 0xffffff, 0.95);
    this.view.alpha = 1;
    this.label.style = new TextStyle({
      fill: 0x101820,
      fontSize: 9,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
    });
  }

  // Recovered-data: StopWatch command 0x14 restores actor+0x3fc from the
  // constructor amount and clears the paused/done presentation for a new round.
  resetRound(): void {
    this.remainingSeconds = this.amountSeconds;
    this.activated = false;
    this.drawBody(0x4fd8ff, 0xffffff, 0.95);
    this.view.alpha = 1;
    this.label.style = new TextStyle({
      fill: 0x101820,
      fontSize: 9,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
    });
    this.syncLabelVisibility();
  }


  presentJudgeLoserPayload(payload: number): void {
    const normalizedPayload = Number.isFinite(payload) ? Math.trunc(payload) >>> 0 : 0;
    this.judgeLoserPresentationPayload = normalizedPayload;
    // Recovered-data: command 0x28 payload observed for StopWatchJudge loser
    // cohorts is 0x7f7f7f7f. The native presentation helper mutates draw data;
    // the browser mirrors that as a neutral grey/dim visual only, not a pause.
    const grey = normalizedPayload & 0x00ffffff;
    this.drawBody(grey || 0x7f7f7f, 0xffffff, 0.88);
    this.view.alpha = 0.82;
    this.label.style = new TextStyle({
      fill: 0xffffff,
      fontSize: 9,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
    });
  }

  get running(): boolean {
    return !this.activated && this.remainingSeconds > STOP_WATCH_DONE_EPSILON_SECONDS;
  }

  update(dt: number): void {
    // Native done-bit state suppresses event-0x12 but does not suppress the
    // countdown subtraction itself; consume an epsilon tail to exact zero so
    // the following event-0xf payload can latch StopWatchScore failure.
    if (this.activated || this.remainingSeconds <= 0) return;
    // FUN_7ff72bb5dff0 receives float dt, subtracts it from the float32 timer,
    // and stores the result back to actor+0x3fc on every update.
    const nextRemainingSeconds = Math.fround(this.remainingSeconds - Math.fround(dt));
    this.remainingSeconds = nextRemainingSeconds >= 0 ? nextRemainingSeconds : 0;
    this.syncLabelVisibility();
  }

  private syncLabelVisibility(): void {
    this.label.visible = !this.param3Flag || this.remainingSeconds >= STOP_WATCH_PARAM3_LABEL_THRESHOLD_SECONDS;
  }

  private drawBody(fill: number, stroke: number, alpha: number): void {
    this.body.clear();
    this.body.beginFill(fill, alpha);
    this.body.lineStyle(2, stroke, 0.9);
    this.body.drawCircle(0, 1, 9);
    this.body.endFill();

    this.body.beginFill(stroke, 0.9);
    this.body.drawRoundedRect(-4, -13, 8, 5, 2);
    this.body.endFill();

    this.body.lineStyle(2, stroke, 0.9);
    this.body.moveTo(0, 1);
    this.body.lineTo(0, -5);
    this.body.moveTo(0, 1);
    this.body.lineTo(5, 1);
  }
}

export function stopWatchDisplayText(label: string, amountSeconds: number): string {
  const trimmedLabel = label.trim();
  if (trimmedLabel !== '') return trimmedLabel;
  return amountSeconds > 0 ? String(amountSeconds) : '';
}

export function parseStopWatchParamsFromSpawn(spawn: ActorSpawnDef): StopWatchParams {
  return parseStopWatchParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseStopWatchParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): StopWatchParams {
  for (let index = 0; index <= raw.length - 3; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const amount = raw[index + 2];
    // FUN_7ff72bb5e7e0 reads and stores the Lua numeric payload as float32.
    const amountSeconds = typeof amount === 'number' && Number.isFinite(amount)
      ? Math.fround(amount)
      : 0;
    const controllerName = raw[index + 3];
    return {
      amountSeconds: isPositiveFiniteNumber(amountSeconds) ? amountSeconds : 0,
      controllerName: typeof controllerName === 'string' ? controllerName : undefined,
      eventValue: nativeGetIntParam(raw[index + 4]),
      param3Flag: nativeGetNumericFlag(raw[index + 5]),
    };
  }

  return { amountSeconds: 0, eventValue: 0, param3Flag: false };
}

export function shouldActivateStopWatchForSwitch(switchSpawn: ActorSpawnDef, stopWatchSpawn: ActorSpawnDef): boolean {
  if (stopWatchSpawn.actorName !== 'StopWatch') return false;

  const stopWatchLabel = stopWatchSpawn.label.trim();
  if (stopWatchLabel === '') return false;

  const expectedTarget = 'StopWatch' + stopWatchLabel;
  return switchActivationTargetLabels(switchSpawn).some((target) => target === expectedTarget);
}

function switchActivationTargetLabels(switchSpawn: ActorSpawnDef): string[] {
  const labels = new Set<string>();
  const explicitLabel = switchSpawn.label.trim();
  if (explicitLabel) labels.add(explicitLabel);

  const rawTargetStartIndex = findRawTargetStartIndex(switchSpawn);
  for (let index = rawTargetStartIndex; index < switchSpawn.raw.length; index += 1) {
    const value = switchSpawn.raw[index];
    if (typeof value !== 'string') continue;
    const label = value.trim();
    if (label) labels.add(label);
  }

  return [...labels];
}

function findRawTargetStartIndex(spawn: ActorSpawnDef): number {
  for (let index = 0; index < spawn.raw.length - 1; index += 1) {
    if (spawn.raw[index] === spawn.x && spawn.raw[index + 1] === spawn.y) return index + 2;
  }
  return 6;
}

function isPositiveFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value) && Math.trunc(value) > 0;
}

function nativeGetIntParam(value: ValueAtom | undefined): number {
  return typeof value === 'number' && Number.isFinite(value) ? Math.trunc(value) : 0;
}

function nativeGetNumericFlag(value: ValueAtom | undefined): boolean {
  return typeof value === 'number' && Number.isFinite(value) && value !== 0;
}
