import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom, Vector2 } from '../types';

export interface JumpAreaParams {
  width: number;
  height: number;
  impulseX: number;
  impulseY: number;
}

const DEFAULT_WIDTH = 48;
const DEFAULT_HEIGHT = 48;
const TILE_SPEED = 60;

export class JumpArea {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params: JumpAreaParams;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseJumpAreaParamsFromSpawn(spawn);
    this.rect = {
      x: spawn.x,
      y: spawn.y,
      width: this.params.width,
      height: this.params.height,
    };
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0x7dd3fc, 0.18);
    g.lineStyle(2, 0x38bdf8, 0.72);
    g.drawRoundedRect(0, 0, this.params.width, this.params.height, 6);
    g.endFill();
    g.beginFill(0xffffff, 0.56);
    g.drawRect(this.params.width / 2 - 10, this.params.height / 2 - 2, 20, 4);
    g.endFill();
    this.view.addChild(g);
  }
}

export function parseJumpAreaParamsFromSpawn(spawn: ActorSpawnDef): JumpAreaParams {
  const params = parseJumpAreaAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
  return {
    width: params?.width ?? DEFAULT_WIDTH,
    height: params?.height ?? DEFAULT_HEIGHT,
    impulseX: params?.impulseX ?? 0,
    impulseY: params?.impulseY ?? 0,
  };
}

export function parseJumpAreaAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): JumpAreaParams | undefined {
  for (let index = 0; index <= raw.length - 6; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const width = raw[index + 2];
    const height = raw[index + 3];
    const impulseX = raw[index + 4];
    const impulseY = raw[index + 5];
    if (
      typeof width === 'number'
      && Number.isFinite(width)
      && typeof height === 'number'
      && Number.isFinite(height)
      && typeof impulseX === 'number'
      && Number.isFinite(impulseX)
      && typeof impulseY === 'number'
      && Number.isFinite(impulseY)
    ) {
      return { width, height, impulseX, impulseY };
    }
  }

  return undefined;
}

export function getJumpAreaVelocity(area: JumpArea): Vector2 {
  return {
    x: area.params.impulseX * TILE_SPEED,
    y: area.params.impulseY * TILE_SPEED,
  };
}

export function shouldApplyJumpArea(playerRect: Rect, areaRect: Rect): boolean {
  return playerRect.x < areaRect.x + areaRect.width
    && playerRect.x + playerRect.width > areaRect.x
    && playerRect.y < areaRect.y + areaRect.height
    && playerRect.y + playerRect.height > areaRect.y;
}
