import { chipStyle } from './chips';
import type { MapDef, Rect } from './types';

export class TileMap {
  readonly map: MapDef;

  constructor(map: MapDef) {
    this.map = map;
  }

  get pixelWidth(): number {
    return this.map.width * this.map.chipSize;
  }

  get pixelHeight(): number {
    return this.map.height * this.map.chipSize;
  }

  chipAt(tileX: number, tileY: number): string {
    if (tileX < 0 || tileY < 0 || tileX >= this.map.width || tileY >= this.map.height) {
      return 'MC_OUT_OF_BOUNDS';
    }
    return this.map.table[tileY * this.map.width + tileX] ?? 'MC_NON';
  }

  setChip(tileX: number, tileY: number, chip: string): boolean {
    if (tileX < 0 || tileY < 0 || tileX >= this.map.width || tileY >= this.map.height) {
      return false;
    }
    this.map.table[tileY * this.map.width + tileX] = chip;
    return true;
  }

  isSolidTile(tileX: number, tileY: number): boolean {
    if (tileX < 0 || tileY < 0 || tileX >= this.map.width || tileY >= this.map.height) {
      return true;
    }
    return chipStyle(this.chipAt(tileX, tileY)).solid;
  }

  isSolidPixel(x: number, y: number): boolean {
    return this.isSolidTile(
      Math.floor(x / this.map.chipSize),
      Math.floor(y / this.map.chipSize),
    );
  }

  rectHitsSolid(rect: Rect, movement?: { axis: 'x' | 'y'; sign: number; previousRect: Rect }): boolean {
    if (
      movement?.axis === 'x'
      && (
        (movement.sign < 0 && rect.x + rect.width <= 0)
        || (movement.sign > 0 && rect.x >= this.pixelWidth)
      )
    ) {
      return true;
    }

    const epsilon = 0.001;
    const minTileX = Math.floor(rect.x / this.map.chipSize);
    const minTileY = Math.floor(rect.y / this.map.chipSize);
    const maxTileX = Math.floor((rect.x + rect.width - epsilon) / this.map.chipSize);
    const maxTileY = Math.floor((rect.y + rect.height - epsilon) / this.map.chipSize);

    for (let ty = minTileY; ty <= maxTileY; ty++) {
      for (let tx = minTileX; tx <= maxTileX; tx++) {
        if (this.rectHitsSolidTile(tx, ty)) return true;
      }
    }
    return false;
  }

  private rectHitsSolidTile(tileX: number, tileY: number): boolean {
    // Engine ground truth: map-chip collision is PURELY non-directional. Solidity is a
    // single bit per chip id, and the same predicate is used regardless of approach
    // direction — there are NO one-way / drop-through / jump-through tiles in the engine.
    // Any one-way-like behavior is ACTOR-based (BlinkBlock/MoveWall), never tile-based.
    // So once a chip is solid, it blocks from every side. Non-solid chips (MC_NON and the
    // danger MC_D* tiles) still pass through via the chipStyle().solid gate.
    const chip = this.chipAt(tileX, tileY);
    return chipStyle(chip).solid;
  }
}
