import { Container, Graphics, Sprite } from 'pixi.js';
import { frameTexture } from '../sprites';
import type { TileMap } from '../TileMap';
import type { Rect, Vector2 } from '../types';
import type { Player } from './Player';

export const BREAKOUT_BALL_RADIUS = 12;
export const BREAKOUT_BALL_DIAMETER = BREAKOUT_BALL_RADIUS * 2;
export const BREAKOUT_BALL_BASE_SPEED = 4;
export const BREAKOUT_BALL_LOSS_COUNTDOWN_TICKS = 180;
// Original-RAM factory path FUN_7ff72bb72ae0 applies this vector before
// constructing/registering the synthesized ball.
export const BREAKOUT_BALL_SPAWN_OFFSET_Y = -120;
const BREAKOUT_BALL_CONTACT_EPSILON_SQUARED = 1.1920928955078125e-7;
const BREAKOUT_BALL_FALLBACK_Y_BIAS = 0.05;
const BREAKOUT_BALL_NATIVE_TICK_SECONDS = 1 / 60;
const BREAKOUT_BALL_MAX_UPDATE_SECONDS = 1 / 20;
const BREAKOUT_BALL_CONTACT_SEPARATION = 0.01;
const BREAKOUT_BALL_FINAL_PROBE_OFFSET = 0.5;
const BREAKOUT_BALL_LOSS_VISUAL_END_TICK = 170;
const BREAKOUT_BALL_LOSS_VISUAL_ALPHA_DENOMINATOR = 10;
const BREAKOUT_BALL_LOSS_VISUAL_SCALE_BASE = 1.0499999523162842;
const BREAKOUT_BALL_LOSS_EXCLUDED_CHIPS = new Set([
  'MC_BLK',
  'MC_BWL',
  'MC_BWC',
  'MC_BWR',
]);
const NATIVE_PLAYER_CONTACT_WIDTH = 32;
const NATIVE_PLAYER_CONTACT_HEIGHT = 46;
const NATIVE_PLAYER_CONTACT_OFFSET_FROM_BROWSER_X = 0;
const NATIVE_PLAYER_CONTACT_OFFSET_FROM_BROWSER_Y = 0;
const NATIVE_PLAYER_CONTACT_MASS = 100;
// breakout-paddle-dome: FUN_7ff72bb6b720 body = circle r 25 (DAT_7ff72c62d1c0), placed by FUN_7ff72bb6b250 at the
// avatar row point + (0, -34) (DAT_7ff72c62d1d0). The row point is the cat body {-16, -47, 32, 46} origin.
export const BREAKOUT_PADDLE_RADIUS = 25;
export const BREAKOUT_PADDLE_OFFSET_Y = -34;
export function breakoutPaddleCenter(playerRect: Rect): Vector2 {
  return { x: playerRect.x + 16, y: playerRect.y + 47 + BREAKOUT_PADDLE_OFFSET_Y };
}

export interface BreakoutBallMapContact {
  tileX: number;
  tileY: number;
  normal: Vector2;
}

export class BreakoutBall {
  readonly view = new Container();
  readonly center: Vector2;
  readonly rect: Rect;
  bodyTint = 0xffffff;
  // Native actor-space heading. FUN_7ff72bc16120 applies it once per fixed
  // 1/60 Stage tick; update() converts partial browser frames back to that
  // cadence while keeping the recovered heading in actor-units-per-tick.
  readonly velocity: Vector2 = { x: 0, y: 0 };
  speedMultiplier = 1;
  lossCountdownTicks = 0;
  removalRequested = false;
  private nativeTickAccumulatorSeconds = 0;
  private playerContactFrameStartRect: Rect;
  private playerContactFrameReady = true;
  private readonly body = new Graphics();

  constructor(centerX: number, centerY: number, readonly owner?: Player) {
    this.center = { x: centerX, y: centerY };
    this.rect = {
      x: centerX - BREAKOUT_BALL_RADIUS,
      y: centerY - BREAKOUT_BALL_RADIUS,
      width: BREAKOUT_BALL_DIAMETER,
      height: BREAKOUT_BALL_DIAMETER,
    };
    this.playerContactFrameStartRect = { ...this.rect };

    // Recovered-data: FUN_7ff72bae6430 builds DAT_7ff72c629fd8={0,0,12}
    // as the centered circle body. The native ball UV has not been isolated,
    // so this neutral vector is only the browser fallback presentation for the
    // now-correct synthesized gameplay object.
    this.body.beginFill(0xffffff, 0.96);
    this.body.lineStyle(2, 0x35233f, 0.9);
    this.body.drawCircle(0, 0, BREAKOUT_BALL_RADIUS);
    this.body.endFill();
    this.view.addChild(this.body);
    // breakout-paddle-dome: native ball frames, view {-12, -12, 24, 24} (base BreakoutBall only).
    const ballTexture = new.target === BreakoutBall ? frameTexture((owner ? 'breakout_ball' : 'breakout_ball_free') as any) : undefined;
    if (ballTexture) {
      const sprite = new Sprite(ballTexture);
      sprite.anchor.set(0.5);
      sprite.width = BREAKOUT_BALL_DIAMETER;
      sprite.height = BREAKOUT_BALL_DIAMETER;
      this.view.addChild(sprite);
      this.body.visible = false;
    }
    this.view.x = centerX;
    this.view.y = centerY;
  }

  protected setBodyTint(tint: number): void {
    this.bodyTint = tint & 0xffffff;
    this.body.tint = this.bodyTint;
  }

  update(
    dt: number,
    tileMap: TileMap,
    onMapContact?: (contact: BreakoutBallMapContact) => void,
    onNativeTickStart?: () => void,
  ): BreakoutBallMapContact[] {
    // The later native body scan reads the resolved motion accumulated by this
    // actor PRE. Preserve the outer-frame start for the browser's nominal
    // fixed-tick Player contact pass.
    this.playerContactFrameStartRect = { ...this.rect };
    this.playerContactFrameReady = false;
    if (!Number.isFinite(dt) || dt <= 0) return [];

    const contacts: BreakoutBallMapContact[] = [];
    this.nativeTickAccumulatorSeconds += Math.min(dt, BREAKOUT_BALL_MAX_UPDATE_SECONDS);
    const tickCount = Math.floor(
      (this.nativeTickAccumulatorSeconds + Number.EPSILON)
      / BREAKOUT_BALL_NATIVE_TICK_SECONDS,
    );
    this.playerContactFrameReady = tickCount > 0;
    this.nativeTickAccumulatorSeconds = Math.max(
      0,
      this.nativeTickAccumulatorSeconds - tickCount * BREAKOUT_BALL_NATIVE_TICK_SECONDS,
    );
    for (let tick = 0; tick < tickCount; tick += 1) {
      onNativeTickStart?.();
      const tickContacts = this.advanceNativeTick(tileMap);
      contacts.push(...tickContacts);
      // Native contact dispatch runs inside this fixed actor tick. Preserve
      // that boundary so a speed/map command can affect the next batched tick.
      for (const contact of tickContacts) onMapContact?.(contact);
      if (this.removalRequested) break;
    }
    return contacts;
  }

  applyBreakoutSpeedCommand(payload: number): void {
    // Base BreakoutBall command receiver FUN_7ff72bae63c0 multiplies the
    // current scale, then caps it at DAT_7ff72bcff5c0 = 2.0f.
    this.speedMultiplier = Math.fround(Math.min(
      Math.fround(this.speedMultiplier * payload),
      2,
    ));
  }

  handleMcBr5MapContact(
    contact: BreakoutBallMapContact,
    tileMap: TileMap,
    broadcastSpeedCommand: (payload: number) => void,
  ): boolean {
    const contactedChip = tileMap.chipAt(contact.tileX, contact.tileY);
    if (
      contactedChip !== 'MC_BR1'
      && contactedChip !== 'MC_BR2'
      && contactedChip !== 'MC_BR3'
      && contactedChip !== 'MC_BR4'
      && contactedChip !== 'MC_BR5'
    ) return false;

    // FUN_7ff72bae64f0 accepts the contiguous MC_BR1..MC_BR5 range. Only BR5
    // dispatches the null-name command and row-major downgrade; every accepted
    // breakable then clears the contacted cell to MC_NON.
    if (contactedChip === 'MC_BR5') {
      broadcastSpeedCommand(2);
      for (let tileY = 0; tileY < tileMap.map.height; tileY += 1) {
        for (let tileX = 0; tileX < tileMap.map.width; tileX += 1) {
          if (tileMap.chipAt(tileX, tileY) === 'MC_BR5') {
            tileMap.setChip(tileX, tileY, 'MC_BR2');
          }
        }
      }
    }
    tileMap.setChip(contact.tileX, contact.tileY, 'MC_NON');
    return true;
  }

  tryStartLossFromMapContact(
    contact: BreakoutBallMapContact,
    tileMap: TileMap,
  ): boolean {
    if (this.lossCountdownTicks !== 0 || this.removalRequested) return false;
    if (
      Math.abs(contact.normal.y - 1)
      > BREAKOUT_BALL_CONTACT_EPSILON_SQUARED
    ) return false;

    const contactedChip = tileMap.chipAt(contact.tileX, contact.tileY);
    if (
      BREAKOUT_BALL_LOSS_EXCLUDED_CHIPS.has(contactedChip)
      || isBreakoutBallBreakableChip(contactedChip)
    ) return false;

    // FUN_7ff72bae64f0 starts the inactive body path at 0xb4 ticks, zeros
    // heading, and clears root-body collision bit 0. An out-of-bounds probe is
    // native chip id 0 and intentionally reaches this branch.
    this.lossCountdownTicks = BREAKOUT_BALL_LOSS_COUNTDOWN_TICKS;
    this.velocity.x = 0;
    this.velocity.y = 0;
    this.playerContactFrameReady = false;
    return true;
  }

  trySeedHeadingFromPlayerContact(previousPlayerRect: Rect, currentPlayerRect: Rect): boolean {
    const headingLengthSquared = Math.fround(
      Math.fround(this.velocity.x * this.velocity.x)
      + Math.fround(this.velocity.y * this.velocity.y),
    );
    if (headingLengthSquared > BREAKOUT_BALL_CONTACT_EPSILON_SQUARED) return false;
    return this.tryApplyPlayerContact(previousPlayerRect, currentPlayerRect);
  }

  tryApplyPlayerContact(previousPlayerRect: Rect, currentPlayerRect: Rect, hasPaddleDome = false): boolean {
    if (
      !this.playerContactFrameReady
      || this.lossCountdownTicks !== 0
      || this.removalRequested
    ) return false;
    const previousContactRect = nativePlayerContactRect(previousPlayerRect);
    const currentContactRect = nativePlayerContactRect(currentPlayerRect);
    // breakout-paddle-dome: the dome (radial normal through the paddle centre) first; the cat box is a second
    // surface with the same mass-100 response.
    const domeNormal = hasPaddleDome ? breakoutPaddleDomeNormal(this.center, currentContactRect) : undefined;
    if (domeNormal && this.applyHeavyBodyContact(domeNormal, previousContactRect, currentContactRect)) return true;
    const normal = mixedBodyContactNormal(
      this.playerContactFrameStartRect,
      this.rect,
      previousContactRect,
      currentContactRect,
    );
    if (!normal) return false;
    return this.applyHeavyBodyContact(normal, previousContactRect, currentContactRect);
  }

  /** FUN_7ff72bae64f0 against a mass-100 body (the cat box or its paddle dome); n points from the ball to the body. */
  private applyHeavyBodyContact(normal: Vector2, previousContactRect: Rect, currentContactRect: Rect): boolean {

    // FUN_7ff72bae64f0 reads both bodies' resolved frame motion. A normal
    // Player has mass 100 while the base ball has mass 1; the native
    // immovable-mass boundary makes the ball's effective mass zero, reducing
    // the elastic response to v + 2*(dot(playerMotion,n)-dot(v,n))*n.
    const ballMotionX = Math.fround(this.rect.x - this.playerContactFrameStartRect.x);
    const ballMotionY = Math.fround(this.rect.y - this.playerContactFrameStartRect.y);
    const playerMotionX = Math.fround(currentContactRect.x - previousContactRect.x);
    const playerMotionY = Math.fround(currentContactRect.y - previousContactRect.y);
    const ballNormalMotion = Math.fround(
      Math.fround(ballMotionX * normal.x)
      + Math.fround(ballMotionY * normal.y),
    );
    const playerNormalMotion = Math.fround(
      Math.fround(playerMotionX * normal.x)
      + Math.fround(playerMotionY * normal.y),
    );
    if (!nativeMixedBodyContactAccepts(ballNormalMotion, playerNormalMotion)) return false;

    const replacementNormalMotion = Math.fround(
      Math.fround(
        Math.fround(
          Math.fround(NATIVE_PLAYER_CONTACT_MASS + NATIVE_PLAYER_CONTACT_MASS)
          * playerNormalMotion,
        )
        + Math.fround(-NATIVE_PLAYER_CONTACT_MASS * ballNormalMotion),
      )
      / NATIVE_PLAYER_CONTACT_MASS,
    );
    let candidateX = Math.fround(
      Math.fround(
        ballMotionX - Math.fround(ballNormalMotion * normal.x),
      )
      + Math.fround(replacementNormalMotion * normal.x),
    );
    let candidateY = Math.fround(
      Math.fround(
        ballMotionY - Math.fround(ballNormalMotion * normal.y),
      )
      + Math.fround(replacementNormalMotion * normal.y),
    );
    const candidateLengthSquared = Math.fround(
      Math.fround(candidateX * candidateX)
      + Math.fround(candidateY * candidateY),
    );

    if (candidateLengthSquared <= BREAKOUT_BALL_CONTACT_EPSILON_SQUARED) {
      candidateX = Math.fround(-normal.x);
      candidateY = Math.fround(-normal.y + BREAKOUT_BALL_FALLBACK_Y_BIAS);
    }

    const candidateLength = Math.hypot(candidateX, candidateY);
    if (candidateLength === 0) return false;
    const targetSpeed = Math.fround(BREAKOUT_BALL_BASE_SPEED * this.speedMultiplier);
    this.velocity.x = Math.fround((candidateX / candidateLength) * targetSpeed);
    this.velocity.y = Math.fround((candidateY / candidateLength) * targetSpeed);
    return true;
  }

  private advanceNativeTick(tileMap: TileMap): BreakoutBallMapContact[] {
    if (this.lossCountdownTicks !== 0) {
      this.advanceLossCountdown();
      return [];
    }
    if (this.removalRequested) return [];
    if (!this.normalizeHeading()) return [];

    const movement = {
      x: this.velocity.x,
      y: this.velocity.y,
    };
    const swept = sweepBreakoutBallRect(tileMap, this.rect, movement);
    this.syncFromRect(swept.rect);

    const contacts: BreakoutBallMapContact[] = [];
    for (const normal of swept.directions) {
      const tile = finalLeadingEdgeTile(tileMap, this.rect, normal);
      if (!tile) continue;
      const contact = { ...tile, normal: { ...normal } };
      contacts.push(contact);
      this.reflectHeading(normal);
    }
    return contacts;
  }

  private advanceLossCountdown(): void {
    const visualStep = this.lossCountdownTicks - BREAKOUT_BALL_LOSS_VISUAL_END_TICK;
    if (visualStep >= 0) {
      const exponent = 11 - visualStep;
      const scale = Math.fround(BREAKOUT_BALL_LOSS_VISUAL_SCALE_BASE ** exponent);
      this.view.scale.set(scale);
      this.view.alpha = Math.fround(
        visualStep / BREAKOUT_BALL_LOSS_VISUAL_ALPHA_DENOMINATOR,
      );
    }

    this.lossCountdownTicks -= 1;
    if (this.lossCountdownTicks === 0) {
      this.removalRequested = true;
    }
  }

  private normalizeHeading(): boolean {
    const headingLength = Math.hypot(this.velocity.x, this.velocity.y);
    if (headingLength === 0) return false;

    const targetSpeed = Math.fround(BREAKOUT_BALL_BASE_SPEED * this.speedMultiplier);
    this.velocity.x = Math.fround((this.velocity.x / headingLength) * targetSpeed);
    this.velocity.y = Math.fround((this.velocity.y / headingLength) * targetSpeed);
    return targetSpeed !== 0;
  }

  private reflectHeading(normal: Vector2): void {
    const projection = Math.fround(
      Math.fround(this.velocity.x * normal.x)
      + Math.fround(this.velocity.y * normal.y),
    );
    const doubledProjection = Math.fround(projection + projection);
    let reflectedX = Math.fround(
      this.velocity.x - Math.fround(doubledProjection * normal.x),
    );
    let reflectedY = Math.fround(
      this.velocity.y - Math.fround(doubledProjection * normal.y),
    );
    const reflectedLengthSquared = Math.fround(
      Math.fround(reflectedX * reflectedX)
      + Math.fround(reflectedY * reflectedY),
    );

    if (reflectedLengthSquared <= BREAKOUT_BALL_CONTACT_EPSILON_SQUARED) {
      reflectedX = Math.fround(-normal.x);
      reflectedY = Math.fround(-normal.y + BREAKOUT_BALL_FALLBACK_Y_BIAS);
      const fallbackLength = Math.hypot(reflectedX, reflectedY);
      const targetSpeed = Math.fround(BREAKOUT_BALL_BASE_SPEED * this.speedMultiplier);
      reflectedX = Math.fround((reflectedX / fallbackLength) * targetSpeed);
      reflectedY = Math.fround((reflectedY / fallbackLength) * targetSpeed);
    }

    this.velocity.x = reflectedX;
    this.velocity.y = reflectedY;
  }

  private syncFromRect(rect: Rect): void {
    this.rect.x = Math.fround(rect.x);
    this.rect.y = Math.fround(rect.y);
    this.center.x = Math.fround(this.rect.x + BREAKOUT_BALL_RADIUS);
    this.center.y = Math.fround(this.rect.y + BREAKOUT_BALL_RADIUS);
    this.view.x = this.center.x;
    this.view.y = this.center.y;
  }
}

interface BreakoutBallSweepResult {
  rect: Rect;
  directions: Vector2[];
}

interface BreakoutBallSweepHit {
  time: number;
  normal: Vector2;
}

function sweepBreakoutBallRect(
  tileMap: TileMap,
  startRect: Rect,
  movement: Vector2,
): BreakoutBallSweepResult {
  const rect = { ...startRect };
  let remaining = { ...movement };
  const directions: Vector2[] = [];

  // One cardinal collision removes one component. A second sweep can remove
  // the remaining tangent at a corner; no third independent axis exists.
  for (let pass = 0; pass < 2; pass += 1) {
    const hit = firstSweptTileHit(tileMap, rect, remaining);
    if (!hit) {
      rect.x = Math.fround(rect.x + remaining.x);
      rect.y = Math.fround(rect.y + remaining.y);
      break;
    }

    rect.x = Math.fround(
      rect.x
      + Math.fround(remaining.x * hit.time)
      - Math.fround(hit.normal.x * BREAKOUT_BALL_CONTACT_SEPARATION),
    );
    rect.y = Math.fround(
      rect.y
      + Math.fround(remaining.y * hit.time)
      - Math.fround(hit.normal.y * BREAKOUT_BALL_CONTACT_SEPARATION),
    );
    if (!directions.some((normal) => vectorsEqual(normal, hit.normal))) {
      directions.push(hit.normal);
    }

    const remainderScale = Math.fround(1 - hit.time);
    const afterImpact = {
      x: Math.fround(remaining.x * remainderScale),
      y: Math.fround(remaining.y * remainderScale),
    };
    const blockedProjection = Math.fround(
      Math.fround(afterImpact.x * hit.normal.x)
      + Math.fround(afterImpact.y * hit.normal.y),
    );
    remaining = {
      x: Math.fround(
        afterImpact.x - Math.fround(blockedProjection * hit.normal.x),
      ),
      y: Math.fround(
        afterImpact.y - Math.fround(blockedProjection * hit.normal.y),
      ),
    };
    if (remaining.x === 0 && remaining.y === 0) break;
  }

  return { rect, directions };
}

function firstSweptTileHit(
  tileMap: TileMap,
  rect: Rect,
  movement: Vector2,
): BreakoutBallSweepHit | undefined {
  if (movement.x === 0 && movement.y === 0) return undefined;

  const chipSize = tileMap.map.chipSize;
  const endX = Math.fround(rect.x + movement.x);
  const endY = Math.fround(rect.y + movement.y);
  const minTileX = nativeTileIndex(Math.min(rect.x, endX), chipSize);
  const minTileY = nativeTileIndex(Math.min(rect.y, endY), chipSize);
  const maxTileX = nativeTileIndex(
    Math.max(
      Math.fround(rect.x + rect.width),
      Math.fround(endX + rect.width),
    ),
    chipSize,
  );
  const maxTileY = nativeTileIndex(
    Math.max(
      Math.fround(rect.y + rect.height),
      Math.fround(endY + rect.height),
    ),
    chipSize,
  );
  let earliest: BreakoutBallSweepHit | undefined;

  for (let tileY = minTileY; tileY <= maxTileY; tileY += 1) {
    for (let tileX = minTileX; tileX <= maxTileX; tileX += 1) {
      if (!breakoutBallSampleIsSolid(tileMap, tileX, tileY)) continue;
      const hit = sweptRectAgainstTile(rect, movement, {
        x: tileX * chipSize,
        y: tileY * chipSize,
        width: chipSize,
        height: chipSize,
      });
      if (!hit) continue;
      if (
        !earliest
        || hit.time < earliest.time
        || (
          hit.time === earliest.time
          && hit.normal.y !== 0
          && earliest.normal.y === 0
        )
      ) {
        earliest = hit;
      }
    }
  }
  return earliest;
}

function sweptRectAgainstTile(
  rect: Rect,
  movement: Vector2,
  tileRect: Rect,
): BreakoutBallSweepHit | undefined {
  const xTimes = sweptAxisTimes(rect.x, rect.width, tileRect.x, tileRect.width, movement.x);
  const yTimes = sweptAxisTimes(rect.y, rect.height, tileRect.y, tileRect.height, movement.y);
  if (!xTimes || !yTimes) return undefined;

  const entryTime = Math.fround(Math.max(xTimes.entry, yTimes.entry));
  const exitTime = Math.fround(Math.min(xTimes.exit, yTimes.exit));
  if (
    entryTime > exitTime
    || entryTime < 0
    || entryTime > 1
    || (xTimes.entry < 0 && yTimes.entry < 0)
  ) {
    return undefined;
  }

  // Native DDA checks horizontal only for tX < tY. Equality therefore takes
  // the vertical boundary first.
  const normal = xTimes.entry > yTimes.entry
    ? { x: Math.sign(movement.x), y: 0 }
    : { x: 0, y: Math.sign(movement.y) };
  if (normal.x === 0 && normal.y === 0) return undefined;
  return { time: entryTime, normal };
}

function sweptAxisTimes(
  start: number,
  size: number,
  tileStart: number,
  tileSize: number,
  movement: number,
): { entry: number; exit: number } | undefined {
  const end = Math.fround(start + size);
  const tileEnd = Math.fround(tileStart + tileSize);
  if (movement > 0) {
    return {
      entry: Math.fround(Math.fround(tileStart - end) / movement),
      exit: Math.fround(Math.fround(tileEnd - start) / movement),
    };
  }
  if (movement < 0) {
    return {
      entry: Math.fround(Math.fround(tileEnd - start) / movement),
      exit: Math.fround(Math.fround(tileStart - end) / movement),
    };
  }
  // Native tangent-span enumeration includes the chip touched by the body's
  // maximum edge, but excludes the chip ending exactly at its minimum edge.
  if (end < tileStart || start >= tileEnd) return undefined;
  return { entry: Number.NEGATIVE_INFINITY, exit: Number.POSITIVE_INFINITY };
}

function finalLeadingEdgeTile(
  tileMap: TileMap,
  rect: Rect,
  normal: Vector2,
): { tileX: number; tileY: number } | undefined {
  const chipSize = tileMap.map.chipSize;
  if (normal.x !== 0) {
    const probeX = normal.x > 0
      ? rect.x + rect.width + BREAKOUT_BALL_FINAL_PROBE_OFFSET
      : rect.x - BREAKOUT_BALL_FINAL_PROBE_OFFSET;
    const tileX = nativeTileIndex(probeX, chipSize);
    const minTileY = nativeTileIndex(rect.y, chipSize);
    const maxTileY = nativeTileIndex(rect.y + rect.height, chipSize);
    for (let tileY = minTileY; tileY <= maxTileY; tileY += 1) {
      if (breakoutBallSampleIsSolid(tileMap, tileX, tileY)) return { tileX, tileY };
    }
    return undefined;
  }

  const probeY = normal.y > 0
    ? rect.y + rect.height + BREAKOUT_BALL_FINAL_PROBE_OFFSET
    : rect.y - BREAKOUT_BALL_FINAL_PROBE_OFFSET;
  const tileY = nativeTileIndex(probeY, chipSize);
  const minTileX = nativeTileIndex(rect.x, chipSize);
  const maxTileX = nativeTileIndex(rect.x + rect.width, chipSize);
  for (let tileX = minTileX; tileX <= maxTileX; tileX += 1) {
    if (breakoutBallSampleIsSolid(tileMap, tileX, tileY)) return { tileX, tileY };
  }
  return undefined;
}

function breakoutBallSampleIsSolid(tileMap: TileMap, tileX: number, tileY: number): boolean {
  if (tileMap.map.width <= 0 || tileMap.map.height <= 0) return false;
  // Native chip sampling clamps an out-of-range probe to the nearest edge
  // cell. TileMap's generic out-of-range-solid rule is Player-specific and
  // would create a false BreakoutBall boundary wall.
  const sampledX = Math.max(0, Math.min(tileMap.map.width - 1, tileX));
  const sampledY = Math.max(0, Math.min(tileMap.map.height - 1, tileY));
  return tileMap.isSolidTile(sampledX, sampledY);
}

function nativeTileIndex(position: number, chipSize: number): number {
  return Math.trunc(Math.fround(position / chipSize));
}

function vectorsEqual(a: Vector2, b: Vector2): boolean {
  return a.x === b.x && a.y === b.y;
}

function isBreakoutBallBreakableChip(chip: string): boolean {
  return (
    chip === 'MC_BR1'
    || chip === 'MC_BR2'
    || chip === 'MC_BR3'
    || chip === 'MC_BR4'
    || chip === 'MC_BR5'
  );
}

function nativePlayerContactRect(browserRect: Rect): Rect {
  // Browser PlayerGeometry keeps its established 26x34 body. Recover the
  // actor anchor locally, then apply DAT_7ff72c62d1a8={-16,-47,32,46}.
  return {
    x: browserRect.x + NATIVE_PLAYER_CONTACT_OFFSET_FROM_BROWSER_X,
    y: browserRect.y + NATIVE_PLAYER_CONTACT_OFFSET_FROM_BROWSER_Y,
    width: NATIVE_PLAYER_CONTACT_WIDTH,
    height: NATIVE_PLAYER_CONTACT_HEIGHT,
  };
}

function mixedBodyContactNormal(
  previousBallRect: Rect,
  currentBallRect: Rect,
  previousPlayerRect: Rect,
  currentPlayerRect: Rect,
): Vector2 | undefined {
  if (!rectsOverlapStrict(currentBallRect, currentPlayerRect)) return undefined;

  const motionX = (
    currentPlayerRect.x - previousPlayerRect.x
    - (currentBallRect.x - previousBallRect.x)
  );
  const motionY = (
    currentPlayerRect.y - previousPlayerRect.y
    - (currentBallRect.y - previousBallRect.y)
  );
  const previousBallRight = previousBallRect.x + previousBallRect.width;
  const previousBallBottom = previousBallRect.y + previousBallRect.height;
  const previousRight = previousPlayerRect.x + previousPlayerRect.width;
  const previousBottom = previousPlayerRect.y + previousPlayerRect.height;
  const relativeRight = previousRight + motionX;
  const relativeBottom = previousBottom + motionY;
  const entries: Array<{ time: number; normal: Vector2 }> = [];

  if (
    motionX > 0
    && previousRight <= previousBallRect.x
    && relativeRight > previousBallRect.x
  ) {
    entries.push({
      time: (previousBallRect.x - previousRight) / motionX,
      normal: { x: -1, y: 0 },
    });
  } else if (
    motionX < 0
    && previousPlayerRect.x >= previousBallRight
    && previousPlayerRect.x + motionX < previousBallRight
  ) {
    entries.push({
      time: (previousBallRight - previousPlayerRect.x) / motionX,
      normal: { x: 1, y: 0 },
    });
  }

  if (
    motionY > 0
    && previousBottom <= previousBallRect.y
    && relativeBottom > previousBallRect.y
  ) {
    entries.push({
      time: (previousBallRect.y - previousBottom) / motionY,
      normal: { x: 0, y: -1 },
    });
  } else if (
    motionY < 0
    && previousPlayerRect.y >= previousBallBottom
    && previousPlayerRect.y + motionY < previousBallBottom
  ) {
    entries.push({
      time: (previousBallBottom - previousPlayerRect.y) / motionY,
      normal: { x: 0, y: 1 },
    });
  }

  const sweptEntry = entries
    .filter((entry) => entry.time >= 0 && entry.time <= 1)
    .reduce<{ time: number; normal: Vector2 } | undefined>(
      (latest, entry) => latest === undefined || entry.time > latest.time ? entry : latest,
      undefined,
    );
  if (sweptEntry) return sweptEntry.normal;

  // A zero-motion or already-overlapping contact has no entry axis. The
  // native mixed-body resolver separates along the shallowest AABB overlap.
  const ballRight = currentBallRect.x + currentBallRect.width;
  const ballBottom = currentBallRect.y + currentBallRect.height;
  const overlaps: Array<{ depth: number; normal: Vector2 }> = [
    {
      depth: currentPlayerRect.x + currentPlayerRect.width - currentBallRect.x,
      normal: { x: -1, y: 0 },
    },
    {
      depth: ballRight - currentPlayerRect.x,
      normal: { x: 1, y: 0 },
    },
    {
      depth: currentPlayerRect.y + currentPlayerRect.height - currentBallRect.y,
      normal: { x: 0, y: -1 },
    },
    {
      depth: ballBottom - currentPlayerRect.y,
      normal: { x: 0, y: 1 },
    },
  ];
  return overlaps.reduce((shallowest, overlap) => (
    overlap.depth < shallowest.depth ? overlap : shallowest
  )).normal;
}

function nativeMixedBodyContactAccepts(
  ballNormalMotion: number,
  playerNormalMotion: number,
): boolean {
  const product = Math.fround(ballNormalMotion * playerNormalMotion);
  if (product <= 0) return ballNormalMotion >= 0;
  return playerNormalMotion <= ballNormalMotion;
}

function rectsOverlapStrict(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.width
    && a.x + a.width > b.x
    && a.y < b.y + b.height
    && a.y + a.height > b.y;
}

/** breakout-paddle-dome: n from the ball centre to the paddle centre while the circles overlap. */
function breakoutPaddleDomeNormal(ballCenter: Vector2, playerRect: Rect): Vector2 | undefined {
  const paddle = breakoutPaddleCenter(playerRect);
  const dx = paddle.x - ballCenter.x;
  const dy = paddle.y - ballCenter.y;
  const distance = Math.hypot(dx, dy);
  if (distance === 0 || distance >= BREAKOUT_PADDLE_RADIUS + BREAKOUT_BALL_RADIUS) return undefined;
  return { x: dx / distance, y: dy / distance };
}
