import { Sprite } from 'pixi.js';
import { frameTexture } from '../sprites';
import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface UpDownEnemyParams {
  movementFlag: number;
}

export const UP_DOWN_ENEMY_WIDTH = 56;
export const UP_DOWN_ENEMY_HEIGHT = 48;
export const UP_DOWN_ENEMY_WAIT_SECONDS = 2;
export const UP_DOWN_ENEMY_TRAVEL_SECONDS = 2.5;
export const UP_DOWN_ENEMY_TRAVEL_Y = -50;

type UpDownEnemyCyclePhase = 0 | 1 | 2 | 3;

export class UpDownEnemy {
  readonly view = new Container();
  readonly params?: UpDownEnemyParams;
  readonly rect: Rect;
  private phase: UpDownEnemyCyclePhase = 0;
  private phaseTimer = 0;
  private readonly baseRectY: number;
  private readonly baseViewY: number;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseUpDownEnemyParamsFromSpawn(spawn);
    this.rect = getUpDownEnemyRect(spawn);
    this.baseRectY = this.rect.y;
    this.baseViewY = spawn.y;
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const flag = this.params?.movementFlag ?? 0;
    const g = new Graphics();
    g.beginFill(0xff4f6d, 0.74);
    g.lineStyle(2, this.params ? 0xffffff : 0x7a3030, 0.9);
    g.drawRoundedRect(-11, -13, 22, 26, 5);
    g.endFill();
    g.beginFill(0x2b1d1d, 0.65);
    g.drawRect(-5, -5, 3, 3);
    g.drawRect(2, -5, 3, 3);
    g.endFill();
    g.lineStyle(1, 0xffd166, 0.48);
    g.moveTo(14, flag < 0 ? 14 : -14);
    g.lineTo(14, flag < 0 ? -14 : 14);
    this.view.addChild(g);
    const texture = frameTexture('updown_enemy' as any);
    if (texture) {
      g.destroy();
      const sprite = new Sprite(texture);
      sprite.x = -30; sprite.y = -26; sprite.width = 60; sprite.height = 52;
      this.view.addChild(sprite);
    }
  }

  update(dt: number): void {
    if (dt <= 0) return;

    // recovered-data: FUN_7ff72bb6d5c0 waits, moves up, waits, then returns.
    if (this.phase === 0) {
      if (UP_DOWN_ENEMY_WAIT_SECONDS <= this.phaseTimer) {
        this.phase = 1;
        this.phaseTimer = 0;
      } else {
        this.phaseTimer += dt;
      }
      return;
    }

    if (this.phase === 1) {
      if (UP_DOWN_ENEMY_TRAVEL_SECONDS <= this.phaseTimer) {
        this.phase = 2;
        this.phaseTimer = 0;
        this.setVerticalOffset(UP_DOWN_ENEMY_TRAVEL_Y);
      } else {
        this.phaseTimer += dt;
        this.setVerticalOffset((this.phaseTimer / UP_DOWN_ENEMY_TRAVEL_SECONDS) * UP_DOWN_ENEMY_TRAVEL_Y);
      }
      return;
    }

    if (this.phase === 2) {
      if (UP_DOWN_ENEMY_WAIT_SECONDS <= this.phaseTimer) {
        this.phase = 3;
        this.phaseTimer = 0;
      } else {
        this.phaseTimer += dt;
      }
      return;
    }

    if (UP_DOWN_ENEMY_TRAVEL_SECONDS <= this.phaseTimer) {
      this.phase = 0;
      this.phaseTimer = 0;
      this.setVerticalOffset(0);
    } else {
      this.phaseTimer += dt;
      this.setVerticalOffset((1 - this.phaseTimer / UP_DOWN_ENEMY_TRAVEL_SECONDS) * UP_DOWN_ENEMY_TRAVEL_Y);
    }
  }

  private setVerticalOffset(offsetY: number): void {
    this.rect.y = this.baseRectY + offsetY;
    this.view.y = this.baseViewY + offsetY;
  }
}

export function getUpDownEnemyRect(spawn: ActorSpawnDef): Rect {
  return {
    x: spawn.x - UP_DOWN_ENEMY_WIDTH / 2,
    y: spawn.y - 22,
    width: UP_DOWN_ENEMY_WIDTH,
    height: UP_DOWN_ENEMY_HEIGHT,
  };
}

export function shouldRespawnPlayerForUpDownEnemy(playerRect: Rect, enemyRect: Rect): boolean {
  return (
    playerRect.x < enemyRect.x + enemyRect.width &&
    playerRect.x + playerRect.width > enemyRect.x &&
    playerRect.y < enemyRect.y + enemyRect.height &&
    playerRect.y + playerRect.height > enemyRect.y
  );
}

export function parseUpDownEnemyParamsFromSpawn(spawn: ActorSpawnDef): UpDownEnemyParams | undefined {
  return parseUpDownEnemyParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseUpDownEnemyParamsAfterCoordinatePair(
  _raw: readonly ValueAtom[],
  _x: number,
  _y: number,
): UpDownEnemyParams | undefined {
  // Recovered-data: the UpDownEnemy factory branch allocates FUN_7ff72bb6d170
  // directly and does not call the createTable param accessors before register.
  return undefined;
}
