import type { ActorSpawnDef } from '../types';

export type SwitchMediatorCommand = 9 | 10;
export type SwitchMediatorBroadcast = (
  target: string,
  command: SwitchMediatorCommand,
  payload: number,
) => void;

function standardParam0(spawn: ActorSpawnDef): unknown {
  const { raw } = spawn;
  if (
    raw[2] !== spawn.actorName
    || raw[3] !== spawn.label
    || raw[4] !== spawn.x
    || raw[5] !== spawn.y
  ) return undefined;
  return raw[6];
}

// Recovered jump02 row shape. Keeping this predicate narrow preserves the older synthetic
// non-empty-label fixtures until their separate producer/receiver families are decoded.
export function isNativeSwitchMediatorSpawn(spawn: ActorSpawnDef): boolean {
  return spawn.actorName === 'SwitchMediator'
    && spawn.label === ''
    && typeof standardParam0(spawn) === 'string';
}

/**
 * Bodyless recovered SwitchMediator actor.
 *
 * FUN_7ff72bb78f60 reads string param 0 into the target prefix. FUN_7ff72bb5fb70
 * broadcasts prefix+(counter+1) before incrementing for command 9, and
 * prefix+counter before decrementing for command 10. The native handler does not clamp.
 */
export class SwitchMediator {
  readonly prefix: string;
  counter = 0;

  constructor(readonly spawn: ActorSpawnDef) {
    const prefix = standardParam0(spawn);
    this.prefix = typeof prefix === 'string' ? prefix : '';
  }

  receiveCommand(command: number, payload: number, broadcast: SwitchMediatorBroadcast): void {
    if (command === 9) {
      broadcast(`${this.prefix}${this.counter + 1}`, 9, payload);
      this.counter += 1;
      return;
    }
    if (command === 10) {
      broadcast(`${this.prefix}${this.counter}`, 10, payload);
      this.counter -= 1;
    }
  }
}
